(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["multimodal"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-vision-encoder-int8-smooth"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-1\">一 · 一次上线事故：精度崩塌发生在视觉塔而不是语言塔</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-2\">二 · 问题定义：要解决的是“编码段固定开销”，不是“整条链路量化”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-3\">三 · 为什么直接INT8会崩：离群值在激活侧，量化步长被单通道绑架</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-4\">四 · 平滑变换的适用前提：离群值可搬移，且搬移后权重仍可量化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-5\">五 · 适用与不适用：三类负载的判定表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-6\">六 · 与相邻方案的边界：为什么不是纯权重量化，也不是per-tensor激活量化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-7\">七 · 平滑量化在视觉编码器上的失效边界与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-8\">八 · 从像素到 patch embedding：平滑因子的挂载点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-9\">九 · 权重量化：离线 GPTQ 与 INT8 权重的静态性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-10\">十 · 激活量化：per-token 动态量化的运行时路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-11\">十一 · INT8 GEMM 与 INT32 累加：Tensor Core 的吞吐兑现</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-12\">十二 · 写回 KV cache：量化边界与末两层兜底</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-13\">十三 · 平滑因子落地的五段流水：从patch embedding到KV写入的输入、输出与代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-14\">十四 · 平滑因子的逐项解剖与指数选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-15\">十五 · 量化 GEMM 的复合公式与 INT32 累加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-16\">十六 · 可实现的伪代码：从校准到前向</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-17\">十七 · 误差传播的一阶推导与末两层保留的依据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-18\">十八 · 分布外回潮与重校准的触发条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-19\">十九 · 请求形态：批量图像与视频帧的编码段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-20\">二十 · 长度分布：N的方差决定批对齐方式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-21\">二十一 · 并发与批大小：SLO以编码段时延为目标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-22\">二十二 · 负载不对时的三种失效形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-23\">二十三 · 与相邻手段的负载分工</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-24\">二十四 · 负载配方：什么请求形态吃得下这套 INT8 平滑量化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-25\">二十五 · 硬件档位：从 SM100 的 INT8 单元到 cuBLASLt 调用面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-26\">二十六 · 并行拓扑：编码段与语言段解耦的放置策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-27\">二十七 · 量化方案：W8A8 的边界与末两层 FP16 兜底</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-28\">二十八 · KV 策略：FP16 写入与跨模态注意力的精度锚点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-29\">二十九 · 调度参数：批对齐、SLO 锚点与校准集覆盖</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-30\">三十 · 可复现配置思路：从校准到上线的检查清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-31\">三十一 · 部署配方的失效边界与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-32\">三十二 · 显存账本：编码器激活与KV写入的分离</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-33\">三十三 · 带宽与INT8 GEMM的实际收益边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-34\">三十四 · 通信：视觉token进入跨模态注意力的搬运成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-35\">三十五 · 功耗与能效：INT8的每瓦收益并不均匀</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-36\">三十六 · 尾延迟与规模崩溃点排序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-37\">三十七 · 工程判断：按段核算而非按算法核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-38\">三十八 · 规模上去以后，先崩的是校准集覆盖度而不是Tensor Core</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-39\">三十九 · 精度崩塌的三种可诊断形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-40\">四十 · OOM 的两种来源与批对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-41\">四十一 · 批抖动与路由不均</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-42\">四十二 · 尾延迟尖刺的定位顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-43\">四十三 · 监控埋点与回滚闸门</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-44\">四十四 · 校准集覆盖度是真正的容量上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-45\">四十五 · 平滑量化的失效面：从离群值回潮到尾延迟尖刺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-46\">四十六 · 选型的第一性问题：你降的是精度还是数量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-47\">四十七 · 决策表：五个判据与对应选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-48\">四十八 · 平滑因子与缩减比率的代价换算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-49\">四十九 · 与量化感知剪枝的联合边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-50\">五十 · 适用条件的三条硬约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-51\">五十一 · 决策落地：一个可执行的判定序列</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vision-encoder-int8-smooth-sec-52\">五十二 · 同族算法的选择边界：平滑量化在什么条件下才值得上</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:482px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 482.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">图像预处理后送入ViT patch embedding，得到[B, N, …</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">在每层LayerNorm后插入per-channel平滑因子s_j，将激活…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">QKV与MLP权重离线GPTQ量化到INT8，激活在线动态per-toke…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">调用cuBLASLt INT8 GEMM在SM100上执行注意力与FFN，…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">视觉token以FP16写入KV cache，供后续跨模态注意力使用</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-1\">一 · 一次上线事故：精度崩塌发生在视觉塔而不是语言塔</h3>\n<p>某多模态服务把语言模型主干换成了W8A8 INT8，语言塔的离线评测与在线指标都稳定，团队据此判断整条链路可以按INT8口径扩容。上线后第一批真实流量里，客服截图、票据扫描件这类高分辨率图像的问答准确率出现肉眼可见的下滑，而同一批请求中纯文本部分的输出质量没有变化。排查路径很直接：把视觉编码器单独拿出来，用FP16与直接INT8两套权重跑同一批图像，patch embedding输出尚可，但进入前几层Transformer后，LayerNorm之后的激活逐通道最大值分布极不均匀——少数通道的幅值比其余通道高出数量级，per-tensor的INT8量化步长被这些离群通道绑架，其余通道的有效位宽被压到几乎为零，注意力logits与FFN中间结果同时失真。这就是ViT激活的通道动态范围问题：它不体现在权重上，因此纯权重量化看不出来；它也不体现在语言塔里，因此语言侧的量化验证无法覆盖。</p>\n<p>事故的代价结构值得注意。视觉token占端到端时延的20–35%，是每一帧、每一张图都要付的固定开销，与生成长度无关；也就是说，视觉编码段既是最容易被人忽视的一段，也是收益最确定的一段。团队最初的直觉是“把视觉塔也INT8就能省一大块”，但直接量化的结果是精度崩塌，于是退回FP16，固定开销原封不动。这个失败案例精确划定了本算法要解决的问题域：让ViT在Blackwell上以W8A8 INT8执行注意力与FFN，同时不因通道离群值而损失精度。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-2\">二 · 问题定义：要解决的是“编码段固定开销”，不是“整条链路量化”</h3>\n<p>把问题写成一句可执行的判断：给定一个以FP16运行的ViT视觉编码器，在SM100/B200上把QKV与MLP的GEMM替换为INT8，要求视觉编码段时延下降，且下游跨模态注意力的输入分布不发生系统性偏移。这里有两个约束必须同时成立。其一是数值约束——LayerNorm后的激活存在通道级离群值，per-tensor量化不可行，必须做通道级处理；其二是接口约束——视觉token最终要以FP16写入KV cache供跨模态注意力使用，量化只发生在编码阶段内部，不能把INT8的视觉token直接塞进KV cache，否则跨模态注意力精度会进一步劣化。</p>\n<p>本算法明确不解决的问题也要说清楚。它不做视觉token的数量压缩或合并——那是token缩减类方法的职责，两者正交：前者降计算精度，后者降token数量，可以叠加但不能互相替代。它不做语言塔的量化，也不做KV cache的量化。它不解决分布外图像的泛化问题，只提供重新校准的手段。它不改变调度与批处理策略，编码段之外的预填/解码时延优化不在其范围内。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-3\">三 · 为什么直接INT8会崩：离群值在激活侧，量化步长被单通道绑架</h3>\n<p>设某层LayerNorm输出为 <span>x</span>，形状[B, N, D]，per-tensor对称INT8量化的步长为 <span>Δ = max(|x|) / 127</span>。当第j个通道的max(|x_j|)比中位数通道高出一个数量级以上时，Δ由该通道决定，其余通道的量化误差被同比放大。ViT的LayerNorm后激活恰恰容易出现这种结构：注意力与FFN的输入通道在训练中形成了少数高幅值通道，它们承载的信息量并不比别的通道多，但数值上支配了整个张量的动态范围。直接INT8的后果不是均匀的精度下降，而是注意力logits在小幅值通道上被量化噪声淹没，表现为密集预测任务（OCR、文档）中细小文字区域的识别错误率上升。</p>\n<p>工程上的代价可以定性描述：若坚持FP16，视觉编码段在B200上按FP16 Tensor Core吞吐执行，这段占端到端时延20–35%的开销无法压缩；若强行INT8，精度崩塌导致业务不可用。两者之间没有中间档，这正是平滑量化要填的缝隙。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-4\">四 · 平滑变换的适用前提：离群值可搬移，且搬移后权重仍可量化</h3>\n<p>算法的核心是把激活侧的离群值搬到权重侧，使两侧的动态范围都变得可量化。对第j个输入通道引入缩放因子 <span>s_j</span>，做等价变换：</p>\n<div class=\"formula\">$$\\tilde{x}_j = \\frac{x_j}{s_j},\\quad \\tilde{W}_{:,j} = W_{:,j}\\cdot s_j,\\quad s_j = \\frac{\\max(|x_j|)}{\\max(|W_{:,j}|)}^{\\alpha},\\ \\alpha\\in[0.4,0.6]$$</div>\n<p>数学上这是恒等变换，GEMM结果不变；数值上它把激活的通道最大值压下去、把对应权重列抬起来。指数α取0.4–0.6而不是1，是因为完全按比值搬移会把权重侧的离群值抬得过高，反噬权重量化；α是两侧动态范围的折中。这个前提决定了算法的适用边界：只有当离群值集中在少数通道、且对应权重列在搬移后仍处于INT8可表示范围时，平滑才有效。若离群值弥散在所有通道，或权重本身已接近INT8饱和，平滑因子的收益会迅速衰减。</p>\n<p>量化后的GEMM写成：</p>\n<div class=\"formula\">$$Y=\\mathrm{deq}\\big(\\mathrm{INT8GEMM}(\\hat{x}_q,\\hat{W}_q)\\big)$$</div>\n<p>累加器为INT32，避免通道级缩放后部分积累加溢出；输出反量化回FP16，保证写入KV cache的视觉token仍是FP16。这一条是整个算法与KV cache量化方案的分界线。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-5\">五 · 适用与不适用：三类负载的判定表</h3>\n<p>把适用边界落成可操作的判定，比定性描述更有用。下表按负载形态给出判断依据，其中精度代价与保留策略均来自该算法的已知行为。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>是否适用</th><th>关键依据</th><th>工程处置</th></tr></thead><tbody><tr><td>通用图文问答、截图理解</td><td>适用</td><td>激活离群值集中在少数通道，平滑后W8A8可承受</td><td>全编码层INT8，视觉token以FP16入KV cache</td></tr><tr><td>OCR、文档高分辨率密集预测</td><td>有条件适用</td><td>精度下降1–2个点，细小文字区域对量化噪声敏感</td><td>保留最后两层FP16兜底，其余层INT8</td></tr><tr><td>红外、医学等分布外图像</td><td>默认不适用</td><td>平滑因子按模型固定，离群值回潮后精度不可控</td><td>按新分布重估s_j，或该路流量退回FP16</td></tr></tbody></table>\n<p>第三行是这套方法最容易被低估的风险。平滑因子由少量校准图像离线估计，部署时零额外运行时开销——这是它相对在线量化的最大优势，也是它最大的刚性：因子一旦固化，遇到校准集未覆盖的成像模态，通道离群值的位置和幅值都会变化，原先搬移得当的通道可能重新变成瓶颈，而原先被压制的通道可能被过度缩放。此时精度退化不是渐进的，而是不可控的。视频多帧场景同理，需按帧分布重估平滑因子，而不能沿用单帧校准的结果。</p>\n<p>还有一条边界属于系统层面而非数值层面：平滑量化只压缩编码段计算，不改变视觉token数量，因此当端到端瓶颈已经转移到解码段或跨模态注意力时，继续在编码段加码的边际收益递减。判断依据是视觉编码段在端到端时延中的占比——当它处在20–35%这个区间时，35–45%的段内降幅对应端到端约7–16%的收益，值得做；当占比被token缩减类方法压到更低时，应先评估瓶颈是否已经迁移。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-6\">六 · 与相邻方案的边界：为什么不是纯权重量化，也不是per-tensor激活量化</h3>\n<p>纯权重INT8在ViT上精度尚可，但计算仍是FP16激活乘以INT8权重，Tensor Core走的是混合精度路径，拿不到Blackwell第五代Tensor Core的INT8吞吐（FP16的2倍）。per-tensor激活量化能吃到INT8吞吐，却在离群通道上崩掉。平滑量化的位置正好在两者之间：它通过通道级缩放把激活也做成INT8，从而真正进入INT8 GEMM路径，同时不引入运行时开销——缩放因子在离线阶段折叠进权重，推理时激活只需按per-token动态量化，除以s_j这一步可以合入量化核。这是它与前两者的本质差别，不是精度与速度的简单折中，而是把“能不能用INT8 GEMM”这个二元问题变成“能不能安全地用”。</p>\n<p>与视觉token压缩类方法的关系需要一句话指路：后者降token数量、前者降计算精度，二者在同一编码段上叠加时，应先确认token缩减没有改变激活的通道分布，否则原先估计的s_j需要重估。与多模态全静态量化类方法的分工同样清晰：静态量化把校准前移到整条链路，平滑量化只处理编码段内最难量化的那一层结构。</p>\n<p>最终落到一个工程判断上：这套算法的价值不在“把ViT量化了”，而在“把视觉编码段的固定开销从FP16的吞吐档位搬到INT8的吞吐档位，且不牺牲密集预测任务的可用精度”。它的适用性由校准集覆盖度决定，它的风险由分布外图像的离群值回潮决定，它的收益上限由视觉编码段在端到端时延中的占比决定。三者任一不成立，就应退回FP16或改用token缩减类方法，而不是在平滑因子上继续调参。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-7\">七 · 平滑量化在视觉编码器上的失效边界与系统代价</h3>\n<p>线上事故的典型形态不是整段推理崩溃，而是精度静默劣化：某文档 OCR 服务在把 ViT 从 FP16 切到直接 INT8 后，整图识别率未见异常，但表格细线与小字号字段开始成片丢失，且只在特定扫描件上复现。根因是 ViT 激活的通道动态范围极大，少数通道的离群值把 per-tensor 量化刻度撑大，其余通道的有效位被压到几乎为零。平滑量化正是针对这一矛盾：它不解决算力不足，也不解决 token 数量过多，只解决“激活离群值导致 W8A8 无法成立”这一个具体问题。若瓶颈在视觉 token 数量或跨模态注意力的带宽，该算法无能为力，需转向 token 压缩或合并。</p>\n<p>机制上，平滑因子在 LayerNorm 之后插入，按通道把激活除以 $s_j$、把对应输入通道权重乘以 $s_j$，离群值由激活搬到权重，再由离线 GPTQ 吸收：</p>\n<div class=\"formula\">$$\\tilde{x}_j = \\frac{x_j}{s_j},\\quad \\tilde{W}_{:,j} = W_{:,j}\\cdot s_j,\\quad s_j = \\frac{\\max(|x_j|)}{\\max(|W_{:,j}|)}^{\\alpha},\\ \\alpha\\in[0.4,0.6]$$</div>\n<p>随后 QKV 与 MLP 走 cuBLASLt INT8 GEMM，INT32 累加后反量化回 FP16，视觉 token 仍以 FP16 写入 KV cache。代价结构必须看清：收益只落在编码段，材料给出该段时延降低约 35–45%，INT8 峰值吞吐为 FP16 的 2 倍；但视觉 token 占端到端时延 20–35%，意味着端到端收益被这一比例封顶，解码段与跨模态注意力不受益。显存侧同样只省编码期激活，KV cache 不缩小。</p>\n<p>失效条件有三类，工程上必须前置判断。<table class=\"mini\"><thead><tr><th>场景</th><th>失效机理</th><th>处置</th></tr></thead><tbody><tr><td>OCR/文档等高分辨率密集预测</td><td>小目标特征对量化噪声敏感，精度降 1–2 个点</td><td>保留最后两层 FP16 兜底</td></tr><tr><td>红外、医学等分布外图像</td><td>平滑因子按模型固定，离群值回潮，精度不可控</td><td>按域重新校准，扩展校准集覆盖</td></tr><tr><td>视觉 token 也量化进 KV cache</td><td>跨模态注意力输入精度进一步劣化</td><td>量化严格限定在编码阶段</td></tr></tbody></table>规模上限受校准集覆盖度约束，视频多帧场景还需按帧分布重估平滑因子，否则同一因子在不同帧上迁移性变差。判断准则很直接：若编码段占比高、输入分布稳定、任务非密集预测，该方案是低风险高回报；反之应保留 FP16 末层并接受部分收益损失。</p>\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-8\">八 · 从像素到 patch embedding：平滑因子的挂载点</h3>\n<p>图像预处理（resize、归一化、可能的色彩空间变换）之后，ViT 的第一站是 patch embedding：把 [H, W, 3] 的图像切成 P×P 的 patch，展平成 [B, N, D] 的 FP16 激活张量，N = HW/P²。这一步本身是卷积或线性投影，通常不在量化范围内——它是整个平滑量化流水线的输入端，决定了后续所有通道级统计量的分布形态。工程上要盯住的是 N 的量级：高分辨率图像（文档、OCR 场景）会让 N 迅速膨胀到数千，而视频多帧输入则把 B 也推高，两者共同决定编码段显存占用与 GEMM 的 M 维规模。</p>\n<p>平滑因子 s_j 的挂载点不在 patch embedding 之后，而在<strong>每一层 LayerNorm 之后</strong>。原因是 LayerNorm 输出的激活在通道维度上方差被归一化，但<strong>通道间的动态范围差异</strong>并未消除——某些通道天然携带大幅值离群值（对应高频纹理、边缘响应），这些通道正是 per-tensor INT8 量化崩塌的根源。把 s_j 插在 LayerNorm 与 QKV 投影之间，等于在数据流最窄的咽喉处做一次通道级重平衡。每个 s_j 是标量，D 个通道就是 D 个标量，随模型固定、离线估计、部署时以常量折叠进权重，运行时只多一次逐通道乘法（可融合进 LayerNorm 的 epilogue），代价可忽略。</p>\n<p>这一步的输入是 LayerNorm 输出的 FP16 激活 [B, N, D]，输出是除以 s_j 后的激活与乘以 s_j 的权重，二者数学等价、数值分布不同。代价体现在校准阶段：需要少量校准图像跑一遍前向，统计每个通道的 max(|x_j|) 与对应权重列的 max(|W_{:,j}|)，按公式</p>\n<div class=\"formula\">$$s_j = \\frac{\\max(|x_j|)}{\\max(|W_{:,j}|)}^{\\alpha},\\ \\alpha\\in[0.4,0.6]$$</div>\n<p>求解。α 是平滑强度的折中旋钮：α 太小，离群值搬不干净，激活仍有大动态范围；α 太大，权重被过度放大，权重量化误差上升。0.4–0.6 的区间是机制给出的经验带，落在这个带内即可，不需要逐层调参。举例：某通道激活 max 为 12.0、对应权重列 max 为 0.5，取 α=0.5 得 s_j≈4.9，激活被压到 2.4 量级、权重被抬到 2.45 量级，两者都落进 INT8 的对称量化区间内。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-9\">九 · 权重量化：离线 GPTQ 与 INT8 权重的静态性</h3>\n<p>平滑变换完成后，QKV 与 MLP 的权重进入离线量化环节。这里用的是 GPTQ——基于 Hessian 近似的逐层后训练量化，把 FP16 权重压到 INT8，且量化误差在给定校准集上被二阶信息加权最小化。关键工程属性是<strong>离线、一次性、与请求无关</strong>：权重 INT8 在模型加载时即确定，不随批大小、不随输入图像变化。这意味着权重侧没有运行时开销，只有存储与带宽收益——INT8 权重使每层权重读取字节数减半，在 Blackwell 的 HBM 带宽约束下直接转化为 GEMM 前的加载时延下降。</p>\n<p>注意平滑与量化的顺序不可颠倒：必须先乘 s_j 再量化权重。若先量化再乘 s_j，权重已经历一次不可逆的舍入，再放大只会放大误差。正确顺序是 W' = W·s_j（FP16 域），然后对 W' 做 GPTQ 得到 Ŵ_q。这一步的输出是 INT8 权重张量加 per-channel（或 per-group）的权重缩放因子，供 GEMM 反量化使用。代价是校准成本：GPTQ 需要校准集跑逐层前向，但只做一次，摊薄到整个部署生命周期后可忽略。举例：一个 D=768 的 ViT 层，QKV 权重矩阵为 768×2304，INT8 后占 1.77 MB，FP16 时占 3.54 MB，单层权重带宽需求减半。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-10\">十 · 激活量化：per-token 动态量化的运行时路径</h3>\n<p>与权重不同，激活必须在线量化——每个请求、每个 token 的激活分布都不同。机制采用 <strong>per-token 动态量化</strong>：对 [B, N, D] 激活，沿 D 维求每个 token 的 max(|x|)，得到该 token 的缩放因子，再把该 token 的 D 个通道统一除以此因子并舍入到 INT8。per-token 而非 per-tensor 的选择直接对应 ViT 激活的通道离群值问题：per-tensor 会被单个极端通道绑架，per-token 则让每个 token 自适应当前动态范围。平滑因子 s_j 在此之上再削一层——它先把通道间的系统性偏差抹平，per-token 量化只需处理残差波动。</p>\n<p>运行时路径的代价是两次归约：求 max 是一次 D 维归约，量化是一次逐元素除法加舍入，反量化在 GEMM 输出侧再做一次逐通道乘法。这些操作在 Blackwell 上可融合进 GEMM 的 prologue/epilogue，但归约本身有延迟——对 N 很大的高分辨率输入，per-token 归约的并行度足够，摊到每个 token 上开销很小；对 N 很小的低分辨率输入，归约的固定开销占比上升，这是小图场景下量化收益被稀释的一个原因。举例：N=1024、D=768 的激活，per-token 量化需 1024 次 768 维归约，在 SM100 上以 warp 级归约展开，延迟被 GEMM 主循环掩盖。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-11\">十一 · INT8 GEMM 与 INT32 累加：Tensor Core 的吞吐兑现</h3>\n<p>量化后的激活与权重送入 cuBLASLt 的 INT8 GEMM，在 SM100 的第五代 Tensor Core 上执行注意力投影与 FFN。累加器是 INT32——这是 INT8 乘加不溢出的保证：两个 INT8 相乘得 16 位积，K 维累加需要 32 位才不溢出，K=768 时最坏情况仍安全。输出经反量化回到 FP16：</p>\n<div class=\"formula\">$$Y=\\mathrm{deq}\\big(\\mathrm{INT8GEMM}(\\hat{x}_q,\\hat{W}_q)\\big)$$</div>\n<p>反量化是逐通道乘 s_j 的逆变换再乘权重缩放因子，融合在 epilogue 里，不产生额外 kernel。吞吐兑现的关键在于 Blackwell 第五代 Tensor Core 的 INT8 峰值吞吐是 FP16 的 2 倍——同样的 MAC 数，INT8 路径的理论时延减半。实际收益被三个因素打折：反量化 epilogue 的额外指令、per-token 量化的归约延迟、以及注意力 softmax 仍须 FP16（softmax 不在 INT8 路径上）。机制给出的编码段时延降低约 35–45%，正是这些折扣后的净值。举例：某层 QKV 投影 M=B·N、K=768、N=2304，FP16 下受 Tensor Core 吞吐限制，INT8 下同一 GEMM 的指令周期减半，叠加权重带宽减半，该层时延接近腰斩；但 softmax 与 LayerNorm 仍是 FP16，整段编码的加速比因此落在 35–45% 而非 50%。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-12\">十二 · 写回 KV cache：量化边界与末两层兜底</h3>\n<p>GEMM 输出反量化回 FP16 后，视觉 token 以 <strong>FP16 写入 KV cache</strong>，供后续跨模态注意力读取。这是整条流水线的收口，也是量化边界所在：量化仅限编码阶段，KV cache 不量化。原因直接——跨模态注意力对视觉 token 的数值精度敏感，若把视觉 token 也压成 INT8 写入 KV cache，注意力打分与加权求和的误差会叠加到语言模型侧，精度进一步劣化。工程判断是：编码段省下的时延已经兑现，KV cache 的带宽与容量代价留给显存管理手段（分页、复用）去处理，不在这里二次压缩。</p>\n<p>末两层保留 FP16 是另一条兜底规则。高分辨率密集预测任务（OCR、文档）对细粒度空间结构敏感，末两层的激活离群值最集中、量化误差最易传导到 patch 级输出，机制材料给出这类任务精度下降 1–2 个点，保留末两层 FP16 可把损失压回可接受范围。代价是末两层仍走 FP16 GEMM，整段加速比被拉低几个百分点——这是精度与速度的显式交换，不是缺陷。另一个代价是分布外泛化：s_j 按校准集固定，遇到红外、医学图像时激活离群值回潮，per-token 量化面对新的动态范围，精度不可控，必须重新校准。视频多帧场景同理，需按帧分布重估平滑因子。校准集覆盖度因此成为该算法的规模上限——覆盖越广，s_j 越稳；覆盖不足，离群值回潮就是失败模式。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-13\">十三 · 平滑因子落地的五段流水：从patch embedding到KV写入的输入、输出与代价</h3>\n<p>按请求在视觉塔内的流动顺序，这套W8A8平滑量化可以拆成五段，每段的输入输出形态不同，代价落点也不同。第一段是预处理与patch embedding：输入是归一化后的图像张量，输出是形状为[B, N, D]的FP16激活，B为图像或视频帧批大小，N为patch序列长度，D为隐藏维。这一段不量化，保持FP16，因为patch embedding本身是带宽受限的访存操作，量化收益被反量化开销吃掉。代价落在显存：N随分辨率平方增长，高分辨率OCR场景下N可达数千，FP16激活的驻留量直接决定批大小上限。第二段是LayerNorm后的平滑插入：输入是第j通道激活x_j与对应输入通道权重W_{:,j}，输出是缩放后的激活与权重，变换为</p>\n<div class=\"formula\">$$\\hat{x}_j = x_j / s_j,\\quad \\hat{W}_{:,j} = W_{:,j}\\cdot s_j,\\quad s_j = \\left(\\frac{\\max(|x_j|)}{\\max(|W_{:,j}|)}\\right)^{\\alpha},\\ \\alpha\\in[0.4,0.6]$$</div>\n<p>这一步是纯逐通道乘除，运行时开销可忽略，真正的代价在离线校准：s_j由少量校准图像统计得出，按模型固定，部署时零额外运行时开销，但也意味着它无法感知单张输入的分布偏移。</p>\n<p>第三段是权重离线GPTQ量化与激活在线动态per-token量化。权重在部署前完成INT8量化并固化，激活则在每次前向时按token统计最大值得到缩放系数，再量化为INT8。输入是FP16激活，输出是INT8激活张量加一组per-token缩放因子。代价在这里出现分叉：per-token动态量化需要一次额外的归约扫描来求每token的max，这是纯带宽操作，在B200的高带宽下相对GEMM可忽略，但对小batch、短序列的编码请求，归约的固定延迟占比上升，成为低利用率场景的隐性成本。第四段是cuBLASLt INT8 GEMM执行QKV与FFN：输入是INT8激活与INT8权重，输出是INT32累加结果，再经反量化回到FP16。这是收益主战场，第五代Tensor Core的INT8吞吐为FP16的2倍，视觉编码段时延降低约35–45%即来自此处。代价是精度：INT32累加器不溢出，但量化误差在深层累积，OCR、文档等高分辨率密集预测任务精度下降1–2个点，工程上的兜底是保留最后两层FP16，这两层不参与INT8 GEMM，代价是尾部时延无法压缩，端到端加速比因此低于纯GEMM的理论上限。</p>\n<p>第五段是视觉token写入KV cache。输入是反量化后的FP16视觉token，输出是供跨模态注意力读取的KV条目。这一段刻意不量化：若把视觉token也压成INT8写入KV cache，跨模态注意力的精度会进一步劣化，因为语言侧解码器对视觉键值的数值敏感度高于编码器内部。代价落在显存与带宽：视觉token以FP16驻留，占KV cache的固定份额，视频多帧场景下这部分随帧数线性增长，成为长上下文多模态请求的容量瓶颈。由此得到该方案的失效边界表：</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>失效表现</th><th>系统代价落点</th></tr></thead><tbody><tr><td>分布外图像（红外、医学）</td><td>激活离群值回潮，s_j失配</td><td>精度不可控，需重新校准</td></tr><tr><td>高分辨率密集预测</td><td>精度降1–2点</td><td>末两层保留FP16，尾部时延不降</td></tr><tr><td>视频多帧</td><td>帧间分布漂移</td><td>需按帧分布重估s_j，校准成本上升</td></tr><tr><td>视觉token写入INT8 KV</td><td>跨模态注意力劣化</td><td>不可接受，必须保持FP16</td></tr></tbody></table>\n<p>工程判断上，这套方案的适用规模受校准集覆盖度限制而非参数量：校准图像覆盖的分布越窄，s_j越锐利，加速越稳；覆盖越宽，s_j越保守，离群值抑制越弱。它与视觉token压缩、合并类方法正交——前者降计算精度，后者降token数量，二者叠加时需注意压缩后的token分布变化会使原s_j失配，须重新校准。部署时的关键取舍是末两层FP16的边界画在哪：画得早则精度稳、加速少，画得晚则加速足、密集预测任务风险高，这条边界应按业务SLO中视觉段时延目标与精度容忍度共同确定，而非按模型层数一刀切。</p>\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-14\">十四 · 平滑因子的逐项解剖与指数选择</h3>\n<p>公式的第一项是通道级缩放：$\\hat{x}_j = x_j / s_j$，$\\hat{W}_{:,j} = W_{:,j}\\cdot s_j$。这里 $x_j$ 是 LayerNorm 输出后第 $j$ 个输入通道上的激活，$W_{:,j}$ 是下游 QKV 或 MLP 权重矩阵中与第 $j$ 个输入通道相连的那一列。注意索引落在“输入通道”上而非输出通道，这是整个推导的关键约束：只有沿 GEMM 的收缩维（contraction dim）做缩放，才能保证乘积不变。写成矩阵形式，若 $S=\\mathrm{diag}(s_1,\\dots,s_D)$，则 $\\hat{X}=XS^{-1}$、$\\hat{W}=SW$，于是 $\\hat{X}\\hat{W}=XS^{-1}SW=XW$，数学上严格等价。任何把 $s_j$ 施加在输出通道上的做法都会破坏这个恒等式，这是实现时最常见的错误来源。</p>\n<p>第二项是因子本身的构造：$s_j = \\left(\\max(|x_j|) / \\max(|W_{:,j}|)\\right)^{\\alpha}$，$\\alpha\\in[0.4,0.6]$。分子是校准集上第 $j$ 通道激活的绝对最大值，分母是对应权重列的绝对最大值。若不取幂（$\\alpha=1$），缩放后激活与权重的动态范围被完全拉平，量化误差在两侧均摊，但激活侧的量化步长被压得过狠，权重侧反而被放大到接近饱和，INT8 的对称量化区间被浪费。$\\alpha&lt;1$ 是一次“部分搬运”：只把激活离群值的一部分转移到权重，保留激活侧一定的余量。$\\alpha$ 落在 0.4–0.6 意味着搬运比例约为平方根量级，这是精度与权重可量化性之间的折中——$\\alpha$ 太小则离群值仍留在激活里，per-token 动态量化会被单个通道拖垮整行的 scale；$\\alpha$ 太大则权重列最大值膨胀，GPTQ 的离线量化误差上升。</p>\n<p>推导的关键一步在于量化误差的重新分配。设激活按 per-token 量化，第 $t$ 个 token 的 scale 为 $\\max_j|\\hat{x}_{t,j}|/127$，则量化噪声正比于该行最大值。平滑前该最大值由离群通道主导，整行所有通道共用一个大步长；平滑后离群通道被 $s_j$ 压低，行最大值下降，其余通道的有效位数上升。代价是权重侧第 $j$ 列的步长变大，但权重是离线 GPTQ 量化的，可以用 Hessian 补偿吸收这部分误差，而激活是在线的、无法补偿。这就是“把误差搬到可补偿的一侧”的完整论证。工程代价上，平滑因子是 $D$ 维向量，对 ViT 的每个 LayerNorm 后各存一份，显存开销可忽略；真正的代价是校准：$\\max(|x_j|)$ 必须在有代表性的图像集上统计，校准集覆盖不足会直接让 $s_j$ 失真。</p>\n<div class=\"formula\">$$s_j=\\Big(\\frac{\\max_{t}|x_{t,j}|}{\\max_{i}|W_{i,j}|}\\Big)^{\\alpha},\\qquad \\hat{x}_{t,j}=\\frac{x_{t,j}}{s_j},\\qquad \\hat{W}_{i,j}=W_{i,j}\\,s_j$$</div>\n<p>具体例子：某 ViT 层 LayerNorm 输出中第 37 通道在若干 patch 上出现幅值远高于邻道的离群值，而对应权重列的最大值偏小，比值大于 1，取 $\\alpha=0.5$ 后 $s_{37}$ 大于 1，激活被除小、权重被乘大；同一行内其他通道的 per-token scale 随之下降，INT8 量化步长收紧。若不做平滑，这一行的 scale 被第 37 通道绑架，其余通道实际有效位宽被压缩，这正是直接 W8A8 精度崩塌的微观机制。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-15\">十五 · 量化 GEMM 的复合公式与 INT32 累加</h3>\n<p>量化后的计算写成 $Y=\\mathrm{deq}\\big(\\mathrm{INT8GEMM}(\\hat{x}_q,\\hat{W}_q)\\big)$，累加器为 INT32。展开看，$\\hat{x}_q$ 是 per-token 动态量化的 INT8 张量，每行一个 scale $\\Delta_t$；$\\hat{W}_q$ 是 GPTQ 产出的 INT8 权重，每列（或每组）一个 scale $\\delta_j$。GEMM 内部做的是 $\\sum_j \\hat{x}_{q,t,j}\\cdot\\hat{W}_{q,i,j}$，两个 INT8 相乘落在 INT32 累加器里，Blackwell 第五代 Tensor Core 的 INT8 通路正是为此设计。反量化在 epilogue 完成：$Y_{t,i}=\\Delta_t\\cdot\\delta_j\\cdot\\mathrm{acc}_{t,i}$，再转回 FP16 写入下一段。这里有一个必须讲清的细节：per-token 的 $\\Delta_t$ 是行向量，per-channel 的 $\\delta_j$ 在收缩维上变化，反量化不能简单提公因子，必须按 $j$ 逐项乘加或在 epilogue 里做外积式缩放，cuBLASLt 的 INT8 GEMM 支持把这两个 scale 作为 epilogue 参数传入，避免额外的 FP32 中间张量往返显存。</p>\n<p>INT32 累加器的位宽论证：ViT 的隐藏维 $D$ 通常在数百到上千量级，INT8 乘积最大 $127\\times127\\approx1.6\\times10^4$，$D=1024$ 时最坏累加约 $1.6\\times10^7$，远低于 INT32 上限 $2.1\\times10^9$，因此单次 GEMM 不会溢出。但若把多个 token 或分组累加进同一缓冲、或做跨层累加，就需要检查余量。这也是为什么累加器选 INT32 而非 INT16：INT16 在 $D$ 较大时会被打爆，而 INT32 的代价是寄存器与 shared memory 带宽翻倍，在 SM100 上表现为 MMA 吞吐略降，但相对 FP16 仍有 2 倍峰值优势。</p>\n<p>系统代价要算清楚：INT8 GEMM 的算术吞吐是 FP16 的 2 倍，但访存并未同比缩减——激活仍是 FP16 读入再在线量化，权重是 INT8 因此权重带宽减半。视觉编码段的瓶颈在 LayerNorm、softmax 与量化/反量化的 elementwise 开销上，GEMM 加速只覆盖注意力与 FFN 的主体。材料给出的编码段时延降低约 35–45%，低于纯 GEMM 的 2 倍，正是因为这些非 GEMM 部分不随精度缩放。工程判断：若把量化/反量化融进 LayerNorm 的 epilogue，可进一步吃掉一部分 elementwise 开销，否则融合收益被 kernel launch 与中间张量写回抵消。</p>\n<p>具体例子：一个 batch 内 $N$ 个视觉 token、隐藏维 $D$，QKV 投影是一次 $[N,D]\\times[D,3D]$ 的 GEMM。FP16 下权重占 $D\\times3D\\times2$ 字节，INT8 下减半；在 B200 上这次 GEMM 的 MMA 指令数减半，但前置的 per-token 求最大值与量化、后置的反量化各是一次 $[N,D]$ 级 elementwise，若单独发 kernel，其耗时在 $N$ 较小时占比显著。这解释了为什么小 batch 视觉编码的实测加速比更接近区间下沿。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-16\">十六 · 可实现的伪代码：从校准到前向</h3>\n<p>把机制落到可实现层面，需要两段代码：离线校准段与前向段。离线段对每层 LayerNorm 后的激活做统计，得到 $s_j$，再用 GPTQ 在“已缩放”的权重上做 INT8 量化——注意顺序，必须先定 $s_j$ 再量化权重，否则 GPTQ 的 Hessian 补偿针对的是未缩放权重，量化误差模型对不上。前向段在 LayerNorm 之后立刻做除法，把结果送入量化 kernel，再调 INT8 GEMM。伪代码思路如下（用文字描述控制流，不写代码块）：对每一层，读取校准激活张量，沿 token 维求每通道绝对最大值，读取对应权重列绝对最大值，按 $\\alpha$ 取幂得 $s$；将 $s$ 存为 FP32 向量并固化进引擎；前向时 LayerNorm 输出除以 $s$（可融进 LayerNorm 的 epilogue），逐 token 求行最大值得 $\\Delta_t$，量化到 INT8，调 cuBLASLt INT8 GEMM 并把 $\\Delta_t$、$\\delta_j$ 作为 epilogue scale，输出 FP16。</p>\n<p>实现上有三个坑。第一，LayerNorm 的 epilogue 融合需要框架支持自定义 epilogue，TensorRT-LLM 的插件路径与 vLLM 的 custom op 路径能力不同，前者更适合把除法与量化一起塞进 LayerNorm kernel。第二，per-token 动态量化要求行最大值在 GEMM 之前算出，这是一次对 $[N,D]$ 的归约，若与量化分成两个 kernel，中间张量要写回显存再读回，带宽代价是 $2\\times N\\times D\\times2$ 字节；融合成一个 kernel 可省掉这一趟。第三，视觉 token 最终以 FP16 写入 KV cache，反量化必须发生在写 cache 之前，不能把 INT8 直接塞进 cache——材料明确指出若视觉 token 也量化为 INT8 写入 KV cache，跨模态注意力精度会进一步劣化。</p>\n<p>系统代价与稳定性：平滑因子离线估计，部署时零额外运行时开销，这是该算法相对量化感知训练的核心优势——不需要改训练流程，只需少量校准图像。校准集的规模直接决定 $s_j$ 的质量，材料未给出具体图像数量，只说明“少量”。对 OCR、文档等高分辨率密集预测任务，精度下降 1–2 个点，需保留最后两层 FP16 兜底；这两层的 GEMM 仍走 FP16 通路，意味着编码段尾部有一段不享受 2 倍吞吐，伪代码里要按层号分支选择 kernel，分支判断应在引擎构建期固化而非运行时判断。</p>\n<p>具体例子：构建引擎时遍历 ViT 的层列表，对前 $L-2$ 层挂 INT8 平滑量化插件、末两层挂 FP16 插件；校准阶段用一批文档图像跑前向，收集每层 LayerNorm 输出，算出 $s$ 后写入插件参数；推理时同一引擎对文档图像走 INT8 主干加 FP16 尾部，对分布外图像则因 $s$ 失配而精度不可控，需触发重新校准流程。这条分支逻辑本身就是工程判断：把“是否需要重校准”做成部署侧的监控指标，而非指望一套因子打天下。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-17\">十七 · 误差传播的一阶推导与末两层保留的依据</h3>\n<p>把量化误差写成加性噪声：$\\hat{x}_q = \\hat{x} + \\epsilon_x$、$\\hat{W}_q = \\hat{W} + \\epsilon_W$，则 GEMM 输出误差一阶近似为 $\\Delta Y \\approx \\epsilon_x\\hat{W} + \\hat{X}\\epsilon_W$。平滑变换把 $\\epsilon_x$ 的方差按 $1/s_j^2$ 缩放、把 $\\epsilon_W$ 的方差按 $s_j^2$ 缩放，两项之积对 $s_j$ 不敏感——这正是“搬运”而非“消除”误差的数学表述。真正变化的是两项的相对权重：平滑后 $\\epsilon_x\\hat{W}$ 项被压低，$\\epsilon_W\\hat{X}$ 项被抬高，而后者可被 GPTQ 的 Hessian 逆补偿，前者不能。所以净效果是总误差下降，下降幅度取决于 GPTQ 对权重误差的吸收能力，这也解释了为什么 $\\alpha$ 不能取 1：取 1 时权重误差被抬得过高，GPTQ 也吸收不完。</p>\n<p>末两层保留 FP16 的依据来自误差传播的层级放大。ViT 的注意力与 FFN 堆叠，每层的量化噪声经残差与 LayerNorm 归一化后进入下一层，深层靠近输出、其误差不经后续层平均而直接进入视觉 token 表示，进而影响跨模态注意力。浅层噪声被后续多层部分平滑，深层噪声直达终点。因此把最后两层留在 FP16，等于在误差传播链的末端切断放大路径，用两层 FP16 的时延代价换取密集预测任务上 1–2 个点的精度回收。这是一个明确的性价比判断：末两层 GEMM 占编码段计算量的比例有限，而精度收益落在最敏感的任务上。</p>\n<p>系统代价上，末两层 FP16 意味着编码段时延不会等比例降到 INT8 的理论值，实测 35–45% 的降幅已经包含这部分折损。显存侧，权重只有末两层保持 FP16，其余 INT8，权重占用接近减半；激活侧因在线量化不持久化，峰值显存由最大层的 $[N,D]$ FP16 张量与 INT8 量化缓冲共同决定，后者是前者的四分之一。带宽侧，权重读取减半是主要收益，激活读取未变。</p>\n<p>具体例子：OCR 场景下视觉 token 数量随分辨率上升，深层 token 表示直接参与文本区域的跨模态对齐，末两层若量化，字符边缘的细粒度特征先受损，表现为识别错误率上升而非整体语义漂移。保留末两层 FP16 后，这部分特征以原精度进入 KV cache，跨模态注意力拿到的视觉表示不被二次污染。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-18\">十八 · 分布外回潮与重校准的触发条件</h3>\n<p>平滑因子按模型固定，本质是把校准集上的通道统计当作先验。遇到红外、医学等分布外图像，激活的离群通道位置与幅值都会变化，$s_j$ 不再匹配，离群值回潮，per-token scale 重新被绑架，精度不可控。这不是渐进退化而是断崖式的：某个原本被压制的通道在新分布下幅值暴涨，整行量化步长被拉大，同行其余通道有效位宽骤降。工程上必须把这种情况当作失败模式处理，而不是指望 $\\alpha$ 的鲁棒性兜住。</p>\n<p>触发重校准的判据可以落在运行时统计上：在编码段采集每层 LayerNorm 输出的通道最大值，与固化 $s_j$ 时的统计做比较，若某通道的当前最大值超过校准值一定倍数，即判定分布漂移。这个比较本身有开销——每层一次通道归约，与 per-token 量化所需的行归约可共用同一次 kernel，边际成本低。判据阈值需要按任务设定，材料未给出具体倍数，只说明需重新校准。重校准流程复用离线段代码，用新分布的少量图像重估 $s_j$ 并重跑 GPTQ，引擎需支持因子热更新或重建。</p>\n<p>视频多帧场景是另一个触发源：帧间分布随场景切换变化，材料指出需按帧分布重估平滑因子。若每帧都重估，校准开销进入关键路径，不可接受；可行做法是按场景边界或固定帧窗口批量重估，把 $s_j$ 的更新频率降到场景级。系统代价是重校准期间的引擎重建或参数热替换，前者有停机，后者要求插件参数可写且不破坏已编译 kernel 的常量折叠——若 $s_j$ 被编译进 kernel 常量，热更新就失效，因此实现上应把 $s_j$ 放在常量内存或参数缓冲里而非编译期常量。</p>\n<p>具体例子：医学影像的窗宽窗位与自然图像差异极大，同一 ViT 层在自然图像上被压制的通道在医学图像上成为主导离群通道；若不重校准，INT8 主干输出的视觉 token 表示偏移，跨模态注意力给出错误的区域对齐。工程判断是把“分布外检测 + 重校准”做成部署流水线的一环，与视觉缓存复用、token 压缩等正交手段并列，而不是假设一套因子覆盖所有输入。</p>\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-19\">十九 · 请求形态：批量图像与视频帧的编码段</h3>\n<p>平滑量化INT8的负载配方首先由请求形态决定。它服务的不是逐条交互式单图问答，而是图像或视频帧以批的形式送入ViT编码器的场景：patch embedding输出[B, N, D]的FP16激活，B为批内图像（或帧）数，N为每张图的视觉token数，D为通道维。平滑因子s_j是通道级的，沿D维施加，与B、N无关，因此该算法的收益随B×N的GEMM规模放大而线性兑现——INT8 GEMM在SM100上峰值吞吐为FP16的两倍，只有当单次GEMM的M维（即B×N）足够大、能把cuBLASLt的INT8 kernel喂到接近饱和时，35–45%的编码段时延下降才落在材料给出的区间内。反过来，B=1、N很小的单图请求，GEMM退化为窄矩阵乘，INT8的吞吐优势被kernel launch与反量化开销吃掉，编码段时延改善远低于该区间。这就是负载配方的第一条硬约束：<strong>把视觉编码当作批处理段来调度，而不是逐请求即时编码</strong>。</p>\n<p>视频帧场景把这条约束推得更紧。多帧共享同一编码器，帧间分布若一致，同一组s_j可复用；但材料明确指出视频多帧场景需按帧分布重估平滑因子，意味着负载配方里必须留出校准或分组通道：按场景/摄像头分组，每组一套s_j，组内批处理。分组粒度是工程判断——组太细，校准成本与权重副本（每组一份INT8权重）吃掉显存；组太粗，分布外帧的离群值回潮。一个可操作的配方是：以内容源（而非单帧）为分组键，组内累积足够帧数后离线重估s_j，在线只做per-token动态量化。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-20\">二十 · 长度分布：N的方差决定批对齐方式</h3>\n<p>视觉token数N由分辨率与patch尺寸决定，同一服务里往往并存多种N：缩略图、文档整页、视频帧。材料给出的批大小配方是“按视觉token数[N]与显存对齐”，这句话的工程含义是：批的切分单位不是图像张数B，而是B×N的token总量。因为INT8 GEMM的算力消耗与显存占用都正比于B×N×D，按图像张数凑批会让高分辨率图把批撑爆、低分辨率图让批欠载。正确做法是维护一个token预算T_max，按N降序做bin packing，使每批的Σ N接近T_max而不过界；同一批内若N不一致，padding到批内最大N会浪费GEMM算力，因此更优的是按N分桶、桶内同构批处理。</p>\n<div class=\"formula\">$$\\text{batch cost} \\approx \\frac{B\\cdot N\\cdot D}{T_{\\text{INT8}}}+ \\underbrace{c_{\\text{deq}}(B\\cdot N\\cdot D)}_{\\text{反量化带宽}}$$</div>\n<p>这条代价式说明两件事：其一，吞吐由INT8 Tensor Core的T_INT8主导，B×N越大摊薄越好；其二，反量化把INT32累加器结果写回FP16，是纯带宽开销，随B×N×D线性增长，无法被INT8吞吐掩盖。当N分布长尾严重（少量超大图+大量小图）时，长尾批的反量化带宽占比升高，实际端到端收益从35–45%的上沿向下沿滑落。配方上的对策是把长尾大图单独成批、优先调度，避免它拖住整批的完成时间；小图则高密度凑批以摊薄固定开销。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-21\">二十一 · 并发与批大小：SLO以编码段时延为目标</h3>\n<p>材料给出的SLO口径是“以视觉编码段时延为目标”，未给毫秒级数值。这决定了并发配方的形状：编码段是端到端时延里的固定开销（占20–35%），它与解码段的连续批处理在资源上竞争，但SLO约束落在编码段本身。于是批大小存在双向压力——批越大，INT8 GEMM越饱和、单位token成本越低，但单批编码段时延随B×N增长，逼近SLO上限；批越小，时延好看但吞吐塌陷。工程上的配方是<strong>以编码段时延上限反推最大批token数</strong>：先测出该SLO下B×N的可行上界，再把连续批处理的窗口卡在这个上界内，让编码器始终工作在“时延刚好达标、吞吐最大”的拐点上。</p>\n<p>并发层面还有一个容易被忽略的耦合：视觉token以FP16写入KV cache供跨模态注意力使用，量化仅限编码阶段。这意味着编码段的INT8收益不会传递到KV cache的显存占用上——KV cache的容量规划仍按FP16视觉token计。并发数上升时，KV cache的FP16占用先于编码算力成为瓶颈；此时提高编码批大小只改善算力利用率，不改善显存。配方判断因此是：并发受限于KV cache显存时，优化重点应转向视觉token数量侧的手段（与本算法正交），而不是继续加大编码批。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-22\">二十二 · 负载不对时的三种失效形态</h3>\n<p>第一种是<strong>小批窄GEMM</strong>：B×N过小，INT8 kernel利用率低，反量化开销占比高，编码段时延改善趋近于零，而部署侧已付出离线校准与权重INT8化的工程成本。表现为“上线了但没快”，根因是负载形态与算法假设不匹配，不是量化本身失效。</p>\n<p>第二种是<strong>分布外负载</strong>：平滑因子按模型固定，遇到红外、医学等分布外图像时激活离群值回潮，s_j不再把离群值搬干净，per-token动态量化在回潮通道上截断严重，精度不可控。材料给出的兜底是保留最后两层FP16，但这只护住末两层，中间层的精度劣化仍会传导。负载配方上的对策是把分布外检测前置到路由层：按内容源分组、组内校准，未覆盖的源走FP16路径或先做小样本校准再切INT8。</p>\n<p>第三种是<strong>把视觉token也量化进KV cache</strong>：材料明确这是失败模式，跨模态注意力精度会进一步劣化。负载配方必须把“编码段INT8、KV cache FP16”作为不可越过的边界写进部署配置，任何试图用INT8视觉token压KV cache显存的改动都属于越界，其精度代价不在本算法的收益账内。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>编码段表现</th><th>配方动作</th></tr></thead><tbody><tr><td>大批同构图像</td><td>GEMM饱和，时延降35–45%</td><td>按token预算bin packing，桶内同构</td></tr><tr><td>小批单图</td><td>窄GEMM，收益趋零</td><td>聚合为批处理段，勿逐请求编码</td></tr><tr><td>长尾高分辨率</td><td>反量化带宽占比升高</td><td>长尾单独成批、优先调度</td></tr><tr><td>分布外源（红外/医学）</td><td>离群值回潮，精度不可控</td><td>分组校准或回落FP16</td></tr><tr><td>OCR/文档密集预测</td><td>精度降1–2点</td><td>保留末两层FP16兜底</td></tr></tbody></table>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-23\">二十三 · 与相邻手段的负载分工</h3>\n<p>负载配方还要回答“什么时候不该用它”。与视觉token压缩/合并类手段正交：前者降计算精度，后者降token数量。当负载的瓶颈在KV cache显存或跨模态注意力长度时，降token数量的手段直接命中，而平滑INT8只作用于编码段算力，收益被稀释；当瓶颈在编码段GEMM吞吐、且B×N足够大时，平滑INT8是零运行时开销的首选，因为平滑因子离线估计、部署时无额外算子。配方判断可写成一条分流规则：先看端到端时延里编码段占比是否落在20–35%的固定开销区间，再看批token量能否喂饱INT8 kernel——两条都满足才把该负载路由到INT8编码路径，否则走FP16或先做token侧压缩。</p>\n<p>规模上限受校准集覆盖度限制，材料未给出参数量或分辨率上限。工程含义是：负载配方里的“可服务内容源清单”就是规模边界本身，清单外的源不进INT8路径。校准集覆盖度而非模型规模，才是这条配方真正的容量天花板——每新增一类内容源，就要新增一组s_j与一次离线校准，这是负载扩张时必须计入的运维成本。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-24\">二十四 · 负载配方：什么请求形态吃得下这套 INT8 平滑量化</h3>\n<p>这套方案的经济性来自一个非常具体的比值：视觉编码段占端到端时延的 20–35%，而 INT8 GEMM 在 SM100 上峰值吞吐是 FP16 的 2 倍，实测编码段时延下降约 35–45%。要让这个收益真正兑现，请求必须满足三个形态条件。第一，编码是<b>批量成形的</b>：图像或视频帧以批送入 ViT，patch embedding 后得到规整的 [B, N, D] 激活张量，N 由分辨率与 patch 尺寸决定，B 由调度器按视觉 token 总数与显存对齐后给出。第二，编码段在端到端链路中占比足够高——单图短提示、纯文本追问这类请求里视觉段占比低，量化省下的绝对毫秒数被解码段淹没，收益不可见。第三，输入分布落在校准集覆盖范围内。三者缺一，收益就从“35–45%”滑向“接近零”甚至负值，因为反量化与 FP16 兜底层的切换本身要付调度代价。</p>\n<p>批大小的配方不是“越大越好”，而是由视觉 token 数与 KV cache 写入共同约束。设单请求视觉 token 数为 N，批大小为 B，则编码段激活显存近似正比于 B·N·D·2 字节（FP16 写入 KV cache 的部分另计），而 INT8 GEMM 的算力利用率随 B·N 增大而上升，直到受 TMEM 与 SM 占用率限制。工程上的做法是把 B 调到“单次 GEMM 的 M 维刚好填满 SM 阵列”的位置，再往上加批只会拉长尾延迟而不增吞吐。这也解释了为什么该方案与连续批处理天然合拍：视觉编码是典型的“一次性大块计算”，与解码段的细粒度 token 循环在时间上可以重叠，把编码批做厚、把解码批做薄，是分离式预填/解码架构下最自然的负载切分。</p>\n<div class=\"formula\">$$\\text{编码段收益} \\approx \\frac{T_{\\text{vis}}}{T_{\\text{e2e}}}\\times\\left(1-\\frac{1}{r_{\\text{INT8}}}\\right),\\quad r_{\\text{INT8}}\\approx 2$$</div>\n<p>按此式估算：当视觉段占比 20% 时，端到端收益上限约 10%；占比 35% 时约 17.5%。这就是负载配方第一条硬约束——<b>视觉段占比低于约 15% 的请求形态不值得开这套量化</b>，因为收益被非编码段稀释，而精度风险（OCR、文档类下降 1–2 个点）却是全局的。反过来，高分辨率密集预测、多图/多帧输入、文档 OCR 批处理这类视觉 token 密集的形态，正是配方的最佳点位；但同一批请求又恰好落在精度敏感区，所以必须保留最后两层 FP16 兜底，这会让实际收益略低于 35–45% 的上界。</p>\n<table class=\"mini\"><thead><tr><th>请求形态</th><th>视觉段占比</th><th>配方判断</th><th>主要代价</th></tr></thead><tbody><tr><td>单图 + 长文本解码</td><td>低</td><td>不开量化，FP16 直跑</td><td>收益被解码段淹没</td></tr><tr><td>多图/视频帧批处理</td><td>高</td><td>最佳点位，厚编码批</td><td>需按帧分布重估平滑因子</td></tr><tr><td>OCR/文档高分辨率</td><td>高</td><td>开量化 + 末两层 FP16</td><td>精度降 1–2 个点</td></tr><tr><td>红外/医学等分布外图像</td><td>不定</td><td>需重新校准后再开</td><td>离群值回潮，精度不可控</td></tr></tbody></table>\n<p>负载不对时的失效是分层的。最轻的一层是<b>批形状错配</b>：B·N 太小导致 INT8 GEMM 的 M 维填不满，Tensor Core 利用率掉下来，2 倍吞吐的理论值拿不到，此时量化只带来反量化开销而无速度收益。中间一层是<b>长度分布漂移</b>：视频多帧场景下每帧的激活分布不同，按单一校准集估出的 s_j 对某些帧不再最优，离群值回潮使 per-token 动态量化的缩放因子被拉爆，个别通道的量化误差放大到影响注意力分数。最重的一层是<b>把量化越界到 KV cache</b>：视觉 token 若也以 INT8 写入 KV cache，跨模态注意力的精度会进一步劣化——本方案的设计边界是“量化仅限编码阶段，视觉 token 以 FP16 写入 KV cache”，越过这条线，省下的那点 KV 显存换不回精度。系统代价上，这三层失效分别表现为吞吐不达标、尾延迟抖动、以及精度不可控，而平滑因子按模型固定、部署时零运行时开销的前提，恰恰意味着运行时没有自适应补偿机制，负载一旦偏离配方就只能靠重新校准来修。</p>\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-25\">二十五 · 硬件档位：从 SM100 的 INT8 单元到 cuBLASLt 调用面</h3>\n<p>部署配方第一层是硬件档位选择。视觉编码器INT8平滑量化的收益完全建立在第五代Tensor Core的INT8吞吐之上：SM100上INT8 GEMM峰值吞吐为FP16的2倍，这个倍率是整条链路时延收益的物理上限。工程上要做的不是\"选B200还是B300\"，而是确认三件事同时成立——目标GPU的SM架构为SM100/SM103、cuBLASLt版本暴露INT8 GEMM路径、以及算子形状能落进该路径的tile约束。ViT的QKV与MLP GEMM形状相对规整（[B·N, D] × [D, D']一类），比LLM解码阶段的 skinny GEMM 更容易吃满INT8单元，这也是视觉段量化比语言段量化更容易拿到接近峰值吞吐的原因。</p>\n<p>档位判断的量化依据是Amdahl型收益分解：设视觉段占端到端时延比例ρ（材料给出20–35%），视觉段自身加速比为k（INT8理论2倍，实测受反量化与LayerNorm开销拖累），则端到端加速比为</p>\n<div class=\"formula\">$$S_{e2e} = \\frac{1}{(1-\\rho) + \\rho/k}$$</div>\n<p>取ρ=0.30、k=1.8，得S≈1.19；若k掉到1.2（形状不规整、反量化瓶颈），S仅≈1.06。这说明档位选择的核心不是堆硬件，而是保证k不被非GEMM开销吃掉。具体例子：一个batch内视觉token数N较大时，GEMM占比高、k接近理论上限；N很小时LayerNorm与反量化的固定开销占比上升，此时应优先合并请求而不是换卡。代价面：INT8路径的功耗低于FP16同吞吐，但若为凑形状而放大batch，显存带宽会先成为瓶颈——视觉激活[B,N,D]在FP16下写入KV cache的那一步不受量化影响，带宽账单照付。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-26\">二十六 · 并行拓扑：编码段与语言段解耦的放置策略</h3>\n<p>视觉编码段量化后变快，反而暴露了拓扑问题：如果编码器与语言模型同卡串行，视觉段缩短只是把空闲窗口提前，端到端时延由语言段主导，收益被稀释。部署配方因此要求把视觉编码器作为独立可放置单元——可以同卡不同stream，也可以分离到不同GPU，通过NVLink 5搬运FP16视觉token写入目标卡的KV cache。选择依据是视觉token的搬运量与编码段时延的比值：搬运[B,N,D]的FP16张量在NVLink 5带宽下通常远快于重算一遍编码，因此\"编码在一组卡、解码在另一组卡\"的分离式拓扑在视觉token占比高的负载下更优。</p>\n<p>拓扑内的并行维度要分开配置：视觉编码器用张量并行（TP）切分QKV与MLP的INT8 GEMM，切分粒度必须与平滑因子的通道语义对齐——s_j是输入通道级因子，TP沿输出维度切权重时s_j可完整复制到每个rank，沿输入维度切则需保证s_j与权重分片同源，否则反量化后的数值不一致。伪代码思路：</p>\n<div class=\"formula\">$$\\text{rank } r:\\ W^{(r)}_{:,j} = W_{:,j}\\cdot s_j\\ \\text{(输入维切分时按j区间取s)};\\quad Y^{(r)}=\\mathrm{deq}(\\mathrm{INT8GEMM}(\\hat{x}_q, \\hat{W}^{(r)}_q))$$</div>\n<p>代价面：TP度增加会放大AllReduce通信量，视觉段时延本就只占20–35%，通信开销占比会被放大；因此视觉编码器的TP度通常低于语言段，宁可单卡跑满INT8也不做高TP。具体例子：NVL72机架内把视觉编码器固定在少数几颗B200上做TP=2或TP=4，语言段用更大TP/EP，两者通过NIXL做token级传输，避免编码段通信拖累整体SLO。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-27\">二十七 · 量化方案：W8A8 的边界与末两层 FP16 兜底</h3>\n<p>量化方案在部署配方里是分层决策，不是全局开关。材料给出的机制是QKV与MLP权重离线GPTQ到INT8、激活在线动态per-token量化到INT8，累加器INT32，输出反量化回FP16。部署时必须显式划定三条例外线：第一，LayerNorm与softmax保持在FP16，平滑因子插在LayerNorm之后、GEMM之前，不能把缩放折进LayerNorm的仿射参数里（会改变数值路径且难以按通道重估）；第二，最后两层保留FP16，这是对OCR、文档等高分辨率密集预测任务精度下降1–2个点的兜底手段；第三，视觉token写入KV cache时保持FP16，量化仅限编码阶段。</p>\n<p>平滑因子的部署形态是\"离线常量表\"：s_j按校准集估计后固化为每层一张通道向量，运行时零额外开销——这是该方案相对动态per-tensor量化的关键优势，后者需要每batch统计amax，引入同步点。公式上，s_j的指数α∈[0.4,0.6]是迁移强度的旋钮：α偏大把更多离群值搬进权重，激活更平滑但权重量化误差上升；α偏小则激活残留离群值。部署配方建议按任务类型固定α并在校准集上做一次网格扫描，而不是运行时自适应。</p>\n<p>代价面：末两层FP16意味着编码段并非全程INT8，实际加速比低于2倍的理论值，材料给出的35–45%时延下降已经包含这部分折损。具体例子：文档OCR负载下，若把末两层也压到INT8，密集预测精度进一步下滑且不可控，因此配方里把\"末两层FP16\"写成硬约束而非可调项；反过来，在自然图像分类类负载上可评估放开末层，但需重新校准并验证分布外样本。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-28\">二十八 · KV 策略：FP16 写入与跨模态注意力的精度锚点</h3>\n<p>KV策略是本配方中最容易被误改的一环。视觉token以FP16写入KV cache供后续跨模态注意力使用，材料明确指出：若把视觉token也量化为INT8写入KV cache，跨模态注意力精度会进一步劣化。原因是跨模态注意力对视觉token的数值保真度敏感——语言侧query与视觉侧key的点积在低精度下误差累积，且这部分误差不经过编码段的平滑变换补偿。因此部署配方把KV量化与编码量化视为两条独立决策线：编码段可W8A8，KV cache的视觉部分保持FP16。</p>\n<p>显存账要算清楚：视觉token的KV占用与N成正比，高分辨率图像N大，FP16 KV是显存的主要压力点之一。可行的缓解不是降精度，而是配合token缩减类手段（本模块其他条目已述，此处只作指路）降低N，或用分页KV管理把视觉段与语言段分池。公式上，单请求视觉KV字节数为</p>\n<div class=\"formula\">$$\\mathrm{Bytes}_{vis} = 2 \\times L \\times N \\times D_{kv} \\times 2\\ \\text{(FP16)}$$</div>\n<p>其中L为层数、系数2为K与V。代价面：保持FP16使显存带宽占用高于INT8 KV方案，但在Blackwell的HBM带宽下，视觉KV的读写通常不是端到端瓶颈，真正的瓶颈仍是编码段GEMM与语言段解码。具体例子：视频多帧场景下N随帧数线性增长，配方建议按帧分布重估平滑因子（材料指出视频多帧需按帧分布重估），同时KV保持FP16并对帧间做token合并，而不是把KV压到INT8换取显存。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-29\">二十九 · 调度参数：批对齐、SLO 锚点与校准集覆盖</h3>\n<p>调度参数围绕\"视觉段是固定开销\"这一事实设计。批大小按视觉token数N与显存对齐，而不是按请求数对齐——不同分辨率图像的N差异大，按请求数打包会造成GEMM形状抖动、k下降。配方做法是把N分桶（如按patch数区间），同桶请求合批送入ViT，使INT8 GEMM的M维稳定，反量化开销摊薄。SLO锚点设在视觉编码段时延上，材料给出该段降低约35–45%，未给毫秒级数值，因此容量规划应以\"编码段时延占端到端比例从ρ降到ρ/k\"作为约束式，而不是绝对值。</p>\n<p>调度器还需处理校准集覆盖度这一隐性参数：平滑因子按模型固定，遇到分布外图像（红外、医学）时激活离群值回潮，精度不可控。部署配方因此要求按输入域打标签路由——已知域走INT8平滑路径，未知域或低置信样本回退FP16编码（可只回退末两层或整段）。伪代码思路：</p>\n<div class=\"formula\">$$\\text{route}(img)=\\begin{cases}\\text{INT8-smooth}, &amp; \\text{domain}\\in\\mathcal{D}_{calib}\\\\ \\text{FP16 fallback}, &amp; \\text{otherwise}\\end{cases}$$</div>\n<p>代价面：回退路径牺牲时延收益但保住精度，回退比例直接决定平均加速比；若分布外流量占比高，应重新校准而非扩大回退。具体例子：医学影像服务里把红外/超声样本标记为独立域，单独采集少量校准图重估s_j，重估后仍保留末两层FP16作为兜底，调度上按域配额限制INT8路径的流量占比，避免精度事故扩散到全量请求。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-30\">三十 · 可复现配置思路：从校准到上线的检查清单</h3>\n<p>把上述决策收敛成一条可复现路径：先固定模型与任务域，采集少量校准图像估计每层s_j（α在0.4–0.6内扫描取验证集最优），离线GPTQ量化QKV与MLP权重，末两层标记为FP16；再在SM100上验证cuBLASLt INT8 GEMM路径被命中（用profiler确认GEMM kernel类型与累加器INT32），确认LayerNorm与反量化未成为主导开销；随后配置并行拓扑（视觉段低TP、与语言段解耦、NVLink 5/NIXL搬运FP16 token）、KV策略（视觉KV FP16、分池管理）、调度参数（按N分桶合批、按域路由）。每一步都有对应的失败判据：GEMM未命中则k下降、末两层误压则密集预测精度掉点、KV误量化则跨模态注意力劣化、校准域不覆盖则离群值回潮。</p>\n<p>上线后的稳定性监控应盯三个量：INT8路径命中率、回退比例、以及视觉段时延占端到端比例的实际值（用于反推k是否漂移）。工程判断上，这套配方的价值不在单点加速，而在于把\"视觉段固定开销\"变成可预算项——ρ从20–35%的区间收窄为已知常数后，容量规划才能按SLO反推GPU数量。最后落在具体机制上：平滑因子表是离线产物、运行时零开销，因此任何精度漂移都只能来自输入分布变化或末两层配置改动，监控这两处即可闭环，无需在热路径上引入动态量化统计。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-31\">三十一 · 部署配方的失效边界与系统代价</h3>\n<p>这套配方在硬件档位上锁定 SM100/B200 单机八卡、TP=8 的 ViT 并行拓扑：patch embedding 与 LayerNorm 沿 D 维切分，QKV 与 MLP 的 INT8 GEMM 走 cuBLASLt，累加器 INT32，输出反量化回 FP16 后以 FP16 写入 KV cache——量化只发生在编码段，跨模态注意力读到的仍是全精度视觉 token。调度参数上，批大小按视觉 token 数 N 与显存对齐而非按请求数对齐，因为 ViT 的显存占用近似正比于 B·N·D 的激活峰值；SLO 只锚定编码段时延，材料给出该段降低约 35–45%，不给毫秒级绝对值。真正的边界不在吞吐，而在校准集覆盖度：平滑因子 s_j 按模型固定，一旦输入分布漂移，公式 <span class=\"formula\">$$\\tilde{x}_j = \\frac{x_j}{s_j},\\quad \\tilde{W}_{:,j} = W_{:,j}\\cdot s_j,\\quad s_j = \\frac{\\max(|x_j|)}{\\max(|W_{:,j}|)}^{\\alpha},\\ \\alpha\\in[0.4,0.6]$$</span> 中分子 max(|x_j|) 被低估，离群值回潮，W8A8 的量化误差重新压到注意力 logits 上。</p>\n<p>失效条件可以列成一张判定表，工程上按它决定是否退回 FP16 末两层：</p>\n<table class=\"mini\"><thead><tr><th>触发条件</th><th>表现</th><th>处置</th></tr></thead><tbody><tr><td>OCR/文档等高分辨率密集预测</td><td>精度下降 1–2 个点</td><td>保留最后两层 FP16 兜底</td></tr><tr><td>红外、医学等分布外图像</td><td>激活离群值回潮，精度不可控</td><td>按新分布重估 s_j，重新校准</td></tr><tr><td>视频多帧输入</td><td>帧间分布不一致</td><td>按帧分布重估平滑因子</td></tr><tr><td>视觉 token 写入 INT8 KV cache</td><td>跨模态注意力精度进一步劣化</td><td>KV 侧保持 FP16，量化仅限编码</td></tr></tbody></table>\n<p>系统代价要按段拆开算。编码段省下的是 Tensor Core 时间：INT8 峰值吞吐为 FP16 的 2 倍，GEMM 主导的 QKV 与 FFN 因此受益，但 LayerNorm、softmax、反量化这些非 GEMM 算子仍是 FP16 通路，Amdahl 上限决定了端到端收益低于 2 倍，材料给出的 35–45% 正是这一稀释后的结果。显存侧几乎不省：权重减半带来的节省被 FP16 KV cache 与 FP16 末两层抵消，激活峰值仍由 B·N·D 主导，所以批大小不能因为量化而放大。带宽侧，INT8 权重读取减半缓解了 HBM 压力，但反量化写回 FP16 又增加一次搬运，净收益取决于 GEMM 的算术强度。最容易被忽略的是运维代价：平滑因子零运行时开销的前提是分布稳定，一旦业务侧引入新图像模态，就必须停机重跑校准，这段窗口内要么降级到 FP16 全精度、要么接受不可控的精度漂移——配方是否成立，最终取决于校准集能否覆盖线上真实分布，而不是 INT8 吞吐本身。</p>\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-32\">三十二 · 显存账本：编码器激活与KV写入的分离</h3>\n<p>视觉编码阶段上INT8之后，显存占用并不是简单按“权重减半”线性缩放。ViT的权重在整体显存里占比有限，真正随规模膨胀的是激活张量：patch embedding输出[B, N, D]的FP16激活，N随分辨率平方增长，B随批调度增长。平滑量化把QKV与MLP的GEMM输入压到INT8，激活峰值降到FP16的一半，但LayerNorm、残差、softmax路径仍需FP16参与，因此显存曲线是分段下降而非整体减半。工程上要按段核算：编码段激活峰值、末两层FP16保留区、以及视觉token写入KV cache的FP16副本，三者叠加才是真实占用。视觉token以FP16写入KV cache供跨模态注意力使用，量化仅限编码阶段——这条边界决定了KV cache不会因编码器INT8而缩小，规模上去以后KV侧先成为显存硬约束。举例：高分辨率文档批处理时，N放大使编码激活峰值逼近权重占用，此时INT8带来的余量被末两层FP16与KV副本吃掉，实际可增批幅度小于预期。</p>\n<div class=\"formula\">$$M_{\\text{enc}} \\approx \\underbrace{B\\cdot N\\cdot D\\cdot 2}_{\\text{FP16 残差/LN}}+\\underbrace{B\\cdot N\\cdot D\\cdot 1}_{\\text{INT8 GEMM 输入}}+\\underbrace{B\\cdot N\\cdot D\\cdot 2\\cdot L_{\\text{fp16}}}_{\\text{末两层保留}}$$</div>\n<p>这个式子的含义是：INT8只压中间项，首末两项不动。因此显存优化的边际收益随L_fp16占比上升而递减，末两层保留是精度兜底，也是显存账本里不可压缩的固定项。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-33\">三十三 · 带宽与INT8 GEMM的实际收益边界</h3>\n<p>Blackwell第五代Tensor Core的INT8峰值吞吐为FP16的2倍，但编码段时延降低约35–45%，两者之间的差额就是带宽与调度开销吃掉的部分。ViT的GEMM形状是[B·N, D]×[D, D]，当B·N足够大时计算受限，INT8的2倍吞吐能兑现；当批很小或分辨率很低时，GEMM退化为窄矩阵乘，权重读取带宽成为主导，此时INT8把权重字节数减半确实降带宽，但激活的per-token动态量化引入额外的读改写与缩放因子访存，抵消一部分收益。cuBLASLt INT8 GEMM在SM100上执行注意力与FFN，累加器为INT32，输出反量化回FP16，反量化本身是一次全量写回，其带宽代价与输出规模成正比。规模上去以后先崩的往往不是算力而是这条反量化写回路径：输出张量越大，写回越接近HBM带宽上限。具体例子：视频多帧场景下每帧独立编码，批内帧数增加使反量化写回量线性上升，此时即便Tensor Core利用率未饱和，端到端时延也不再随INT8吞吐线性下降。</p>\n<div class=\"formula\">$$T_{\\text{enc}} \\approx \\max\\!\\left(\\frac{\\text{FLOPs}}{\\Pi_{\\text{INT8}}},\\ \\frac{\\text{Bytes}_{\\text{act}}+\\text{Bytes}_{\\text{deq}}}{BW_{\\text{HBM}}}\\right)$$</div>\n<p>工程判断是：先测反量化写回占比，再决定是否值得把更多层纳入INT8。若写回已接近带宽上限，继续扩INT8层数只增加量化误差而不增吞吐。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-34\">三十四 · 通信：视觉token进入跨模态注意力的搬运成本</h3>\n<p>在NVL72这类多GPU拓扑里，视觉编码器常与语言模型分置或按张量并行切分，视觉token需要从编码侧搬到解码侧参与跨模态注意力。量化只发生在编码阶段，搬出去的是FP16 token，因此通信量与token数成正比、与量化无关——这是平滑量化在分布式场景下的一个隐性代价：它压缩了计算，却没有压缩搬运。NVLink 5的带宽足以承载单帧token搬运，但视频多帧、高分辨率密集预测会把token数推高，通信从可忽略变为可见项。更麻烦的是尾延迟：跨模态注意力要求视觉token全部就位才能开始，编码侧最后一批token的完成时间决定解码侧起步时间，形成同步屏障。规模上去以后，这个屏障的抖动比平均带宽更容易先崩。举例：批内混入一张超高分辨率图像，其token数远超同批其他样本，编码段被这一张拖长，整批的跨模态注意力等待时间由最长样本决定，尾延迟被单样本主导。</p>\n<div class=\"formula\">$$T_{\\text{comm}} \\approx \\frac{N_{\\text{vis}}\\cdot D\\cdot 2}{BW_{\\text{NVLink}}},\\quad T_{\\text{tail}}=\\max_{i\\in\\text{batch}}T_{\\text{enc},i}+T_{\\text{comm},i}$$</div>\n<p>对策在调度层而非量化层：按token数分桶、把长样本单独成批，避免单样本拉长整批屏障；平滑因子按帧分布重估只解决精度，不解决这个同步结构。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-35\">三十五 · 功耗与能效：INT8的每瓦收益并不均匀</h3>\n<p>INT8 GEMM在相同FLOPs下功耗低于FP16，但整段编码的功耗由计算、HBM读写、反量化写回共同构成。计算项下降后，带宽项的功耗占比上升，能效曲线出现拐点：继续压计算精度对总功耗的边际改善变小，而反量化与激活量化的额外访存开始主导。对B200/GB200这类高功耗器件，编码段占端到端时延20–35%，其功耗占比通常低于时延占比，因为解码段的自回归是逐token串行、能效更低。因此把INT8用在编码段是能效上合理的取舍：压的是并行度高、能效好的那段。规模上去以后，功耗先崩的场景是长时间高批视频推理——编码段持续满负荷，反量化写回使HBM长时间高位运行，热设计功耗约束触发降频，INT8的吞吐优势被时钟下降侵蚀。具体例子：连续视频流推理中，编码段与解码段交替占用SM，若编码段INT8使单帧时间缩短，SM空转等待解码的比例上升，整机能效反而由解码段决定，此时继续优化编码段收益有限。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-36\">三十六 · 尾延迟与规模崩溃点排序</h3>\n<p>把上述四项放在一起，规模上去以后先崩的顺序可以排出来。第一崩是尾延迟：批内token数方差大时，同步屏障由最长样本决定，INT8降低的是平均编码时间，不改变最长样本的相对拖尾，甚至因量化路径的固定开销使短样本收益更小而方差相对放大。第二崩是KV cache显存：视觉token以FP16写入，量化不触及KV，序列与批增长时KV先触顶。第三崩是反量化写回带宽。第四才是Tensor Core算力。这个排序的工程含义是：扩容时应优先做token分桶与KV侧管理，而非继续加深INT8覆盖层数。平滑因子按模型固定，遇到分布外图像时激活离群值回潮，精度不可控需重新校准——这在规模场景下表现为校准集覆盖度成为规模上限，而非算力上限。对OCR、文档等高分辨率密集预测任务精度下降1–2个点，需保留最后两层FP16兜底，这条兜底在尾延迟上也有代价：末两层FP16使最长样本的编码时间无法被INT8完全压缩。</p>\n<table class=\"mini\"><thead><tr><th>规模增长维度</th><th>先触发的约束</th><th>量化能否缓解</th></tr></thead><tbody><tr><td>批内token方差</td><td>同步屏障尾延迟</td><td>否，需分桶调度</td></tr><tr><td>序列/并发长度</td><td>KV cache显存（FP16）</td><td>否，量化仅限编码段</td></tr><tr><td>分辨率/帧数</td><td>反量化写回带宽</td><td>部分，受写回限制</td></tr><tr><td>校准集覆盖</td><td>分布外精度回潮</td><td>否，需重校准</td></tr></tbody></table>\n<p>这张表的作用是把“哪里先崩”从定性判断变成可核对的约束清单：每一行对应一个可观测指标，扩容前先看该指标是否已接近拐点，再决定是否投入工程改造。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-37\">三十七 · 工程判断：按段核算而非按算法核算</h3>\n<p>平滑量化的系统代价必须按段核算。编码段内部，INT8收益集中在GEMM密集的QKV与MLP，LayerNorm与softmax仍是FP16，末两层保留FP16，这三处构成不可压缩的固定开销；编码段外部，视觉token的FP16 KV写入与跨模态搬运不受量化影响。因此端到端时延的改善上限被“编码段占20–35%”这个比例锁死：即便编码段时延降低35–45%，折算到端到端也只是个位数到十几个百分点的改善，且随解码段占比上升而稀释。规模上去以后，正确的优化顺序是先把token分桶压尾延迟、再把KV侧显存管住、最后才评估是否扩大INT8层覆盖。平滑因子离线估计、部署零额外运行时开销这一条，在规模场景下的真实含义是：它不增加每请求的运行时成本，但把校准集覆盖度变成了运维负担——分布外图像需要重新校准，这是一次离线重跑，不是在线自适应。若把视觉token也量化为INT8写入KV cache，跨模态注意力精度会进一步劣化，这条失败模式在规模场景下会被放大，因为KV副本是唯一随并发线性增长的显存项，动它的诱惑最大而代价最不可控。</p>\n<div class=\"formula\">$$\\Delta T_{\\text{e2e}} \\le r_{\\text{vis}}\\cdot\\eta_{\\text{enc}},\\quad r_{\\text{vis}}\\in[0.20,0.35],\\ \\eta_{\\text{enc}}\\in[0.35,0.45]$$</div>\n<p>这个不等式是容量规划时的第一道筛子：先算端到端改善上限，再判断是否值得为编码段投入INT8改造与校准运维。若解码段占主导，编码段优化的绝对收益有限，应把工程预算转向KV管理与批调度；若编码段占比接近上限且批内token方差可控，INT8平滑量化的收益才真正兑现。最后落在具体机制上：把末两层FP16保留与token分桶绑定为同一套部署策略，前者保精度、后者保尾延迟，两者共同决定规模上限，而平滑因子本身只是这套策略里的一个离线参数。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-38\">三十八 · 规模上去以后，先崩的是校准集覆盖度而不是Tensor Core</h3>\n<p>平滑量化把视觉编码段的时延压缩了约35–45%，但这条收益曲线的斜率随规模变化并不恒定。单卡B200上，INT8 GEMM峰值吞吐是FP16的2倍，编码段因此从端到端时延的20–35%固定开销中被削去一块；可当批大小按视觉token数[N]与显存对齐往上推时，真正的约束从算力转到两处：一是KV cache的写带宽，视觉token仍以FP16写入供跨模态注意力使用，量化只限编码阶段，于是编码越快、写KV的节奏越密，HBM写入与后续跨模态读取代价被放大；二是校准集覆盖度，平滑因子s_j按模型固定、离线估计，规模越大图像分布越杂，离群值回潮的概率越高。用公式看，通道级缩放后的量化误差上界近似为</p>\n<div class=\"formula\">$$\\max_j\\left|\\frac{x_j}{s_j}-Q\\!\\left(\\frac{x_j}{s_j}\\right)\\right|\\cdot s_j \\le \\frac{\\Delta_j}{2}\\cdot s_j,\\quad s_j=\\Big(\\frac{\\max(|x_j|)}{\\max(|W_{:,j}|)}\\Big)^{\\alpha}$$</div>\n<p>其中Δ_j为INT8量化步长。s_j把激活离群值搬到权重侧，代价是权重侧的量化粒度变粗；当某通道在部署分布上的实际幅值远超校准集估计，误差项随s_j线性放大，精度不可控，这正是红外、医学等分布外图像失效的机理。工程判断是：把校准集按场景分桶，每桶独立估s_j，桶数增加带来的只是离线成本，运行时仍是零开销；但分桶过细会让每桶样本不足，s_j方差上升，需在覆盖度与估计稳定性之间取平衡。</p>\n<p>尾延迟的来源与均值不同。编码段被INT8压缩后，单请求的GEMM时间变短，调度器更容易把多个视觉请求拼进同一批，批内token数[N]方差变大，导致跨模态注意力的KV读取出现长尾；同时OCR、文档类高分辨率密集预测需保留最后两层FP16兜底，这两层的FP16 GEMM在整条INT8流水线里成为串行段，批越大其占比越突出，尾延迟由它主导而非INT8段。视频多帧场景还需按帧分布重估平滑因子，帧间分布漂移会让固定s_j在长视频上逐步失配。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先崩的位置</th><th>系统代价形态</th></tr></thead><tbody><tr><td>批内视觉token数[N]上升</td><td>KV cache FP16写入带宽</td><td>编码段省下的时延被写KV抵消，吞吐增益收窄</td></tr><tr><td>图像分布变杂</td><td>校准集覆盖度</td><td>精度掉点，需重新校准，离线成本上升</td></tr><tr><td>高分辨率密集预测占比升</td><td>末两层FP16串行段</td><td>尾延迟由FP16段主导，均值改善被稀释</td></tr><tr><td>视频多帧</td><td>帧间分布漂移</td><td>s_j失配，需按帧重估，运行时零开销前提被打破</td></tr></tbody></table>\n<p>功耗侧的变化是隐性的：INT8 GEMM把编码段算力时间压下去，SM占用率下降，但KV写入与跨模态读取的HBM活动并未同比减少，于是整卡功耗结构从计算主导转向访存主导，能效比的改善小于时延改善。若进一步把视觉token也量化为INT8写入KV cache，跨模态注意力精度会再劣化一档，这条路径在精度敏感场景应直接排除。规模上限因此不在Tensor Core吞吐，而在“校准集能否覆盖部署分布”与“末两层FP16串行段能否被批调度摊薄”这两件事上。</p>\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-39\">三十九 · 精度崩塌的三种可诊断形态</h3>\n<p>平滑量化上线后，精度问题不会以“整体掉点”这种笼统形态出现，而是分成三类可区分、可定位的形态，诊断路径完全不同。第一类是<strong>通道回潮</strong>：平滑因子按校准集固定，遇到分布外图像（红外、医学、低照度监控帧）时，原本被搬到权重侧的离群值重新在激活侧出现，per-token 动态量化把该 token 的量化步长拉爆，单个 token 的 INT8 表示退化为近似二值。第二类是<strong>末层累积</strong>：OCR、文档等高分辨率密集预测任务中，误差在 ViT 末两层被放大到像素级，表现为字符边缘、表格线断裂，材料给出的量级是精度下降 1–2 个点，这正是保留最后两层 FP16 的工程理由。第三类是<strong>KV 侧污染</strong>：若把视觉 token 也量化为 INT8 写入 KV cache，跨模态注意力在读取时精度进一步劣化，症状是答案文本“语法正确但指代错位”——模型描述的是图中另一个区域。</p>\n<p>诊断的关键是把这三类分开观测，而不是看端到端任务分数。工程做法是在编码器出口挂一个 FP16 影子分支（仅离线诊断时开启），对同一批图像分别跑 INT8 主路径与 FP16 影子路径，逐层计算激活的相对误差：</p>\n<div class=\"formula\">$$\\mathrm{relErr}_l=\\frac{\\lVert \\hat{x}^{(l)}_{\\mathrm{int8}}-\\hat{x}^{(l)}_{\\mathrm{fp16}}\\rVert_2}{\\lVert \\hat{x}^{(l)}_{\\mathrm{fp16}}\\rVert_2},\\quad \\mathrm{drift}_j=\\frac{\\max(|x_j|)_{\\mathrm{live}}}{\\max(|x_j|)_{\\mathrm{calib}}}$$</div>\n<p>relErr 逐层上升说明误差在累积，drift_j 显著大于 1 的通道就是回潮通道。前者指向“该保留 FP16 的层不够”，后者指向“该重新校准的通道”。代价是影子分支让诊断批次的显存翻倍、时延翻倍，因此只能作为灰度期的旁路，不能常开。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-40\">四十 · OOM 的两种来源与批对齐</h3>\n<p>视觉编码段的 OOM 与语言侧不同，它几乎总是<strong>批对齐</strong>问题而非 KV cache 问题。ViT 激活形状是 [B, N, D]，N 随分辨率平方增长；批大小按视觉 token 数对齐时，若调度器按“请求数”而非“token 数”组批，一个高分辨率文档页就能把整批的 N 顶到显存上限。平滑量化本身不增加显存（平滑因子是 per-channel 标量，可折叠进权重），但它把 GEMM 的累加器变成 INT32，中间缓冲的字节数与 FP16 路径不同，若沿用 FP16 时代的 workspace 预算就会在边界批次上炸掉。</p>\n<p>第二种来源是<strong>诊断旁路</strong>：影子分支、逐层误差统计缓冲、校准图像缓存三者叠加，在灰度期把显存吃掉一截，表现为“同一配置昨天能跑今天 OOM”。工程判断是给编码段设独立的显存配额与独立的组批器，按 token 数分桶（例如把 N 落在同一区间的请求归批），并在配额内预留固定比例的 workspace 余量给 INT8 GEMM 的 INT32 累加。OOM 发生时不要先降批大小，先看桶边界是否被单个超长样本击穿——降批只会把吞吐打下去，而分桶能保住大多数批次的形状。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-41\">四十一 · 批抖动与路由不均</h3>\n<p>视觉编码是典型的<strong>固定开销段</strong>：它占端到端时延的 20–35%，且这段时延对批内 token 数高度敏感而对批内请求数不敏感。连续批处理在语言侧按 token 步进，到了视觉段却要等一整批图像编码完才放行，于是出现批抖动——批大小在 1 与上限之间来回跳，编码段时延方差远大于均值。抖动本身不致命，致命的是它把下游跨模态注意力的到达时间打散，KV cache 的写入节奏变得不可预测。</p>\n<p>路由不均来自另一侧：多副本部署时，若路由键用请求 ID 哈希，高分辨率请求会随机堆到某个副本上，该副本的编码段排队深度飙升而其他副本空闲。正确做法是按<strong>预估 token 数</strong>做一致性哈希或最少排队路由，让每个副本的 N 总量均衡。监控上要同时看两个量：批大小的变异系数，以及各副本编码段排队深度的基尼系数。前者高说明组批器在等样本，后者高说明路由键选错了。代价是路由层需要知道分辨率，这要求预处理阶段就把图像尺寸透传给调度器——多一跳元数据，换来的是尾延迟尖刺的消失。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-42\">四十二 · 尾延迟尖刺的定位顺序</h3>\n<p>尾延迟尖刺在视觉段有明确的排查顺序，不要从端到端 P99 开始猜。第一步看<strong>单帧编码时延的分布尾部</strong>是否与分辨率相关：若 P99 样本集中在某一分辨率档，问题在组批桶边界或该档的 workspace 不足。第二步看<strong>INT8 GEMM 的 kernel 选择</strong>：cuBLASLt 在 SM100 上对某些形状会退回到非最优 tile，形状恰好落在退化区间的批次就会尖刺，表现为同一批大小下时延双峰。第三步才看<strong>校准漂移</strong>：drift_j 大的通道会让 per-token 量化的 scale 计算路径变长（极值检测与规约），在极端样本上引入额外延迟。</p>\n<p>工程上给尖刺设一个“编码段时延 / 批内 token 数”的归一化指标，比裸时延更能暴露问题：归一化指标平稳而裸时延尖刺，说明是批形状问题；归一化指标本身尖刺，说明是单样本的数值路径问题（回潮通道）。回滚策略与此对应：形状类问题回滚组批配置即可，数值类问题必须回滚到保留末两层 FP16 甚至整段 FP16，因为平滑因子是离线固定的，运行时无法对单个样本补救。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>首要指标</th><th>定位手段</th><th>回滚粒度</th></tr></thead><tbody><tr><td>密集预测掉点</td><td>逐层 relErr</td><td>FP16 影子分支对比</td><td>末两层回 FP16</td></tr><tr><td>分布外精度不可控</td><td>通道 drift_j</td><td>按域重跑校准集</td><td>整段回 FP16 或重校准</td></tr><tr><td>OOM</td><td>批内 N 分布</td><td>桶边界与 workspace 预算</td><td>改组批桶，不降吞吐</td></tr><tr><td>批抖动</td><td>批大小变异系数</td><td>组批器等待策略</td><td>回滚组批参数</td></tr><tr><td>路由不均</td><td>副本排队深度基尼</td><td>路由键改为 token 数</td><td>回滚路由策略</td></tr><tr><td>尾延迟尖刺</td><td>时延/token 归一化</td><td>kernel 形状退化区排查</td><td>形状类改配置，数值类回精度</td></tr></tbody></table>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-43\">四十三 · 监控埋点与回滚闸门</h3>\n<p>监控要落在三个位置，缺一不可。编码器入口埋<strong>分辨率与预估 token 数</strong>，用于批对齐与路由的事后归因；每层 LayerNorm 后埋<strong>通道极值采样</strong>（按固定间隔抽样通道，不做全通道规约以免拖慢主路径），用于 drift_j 的在线近似；编码器出口埋<strong>输出统计量</strong>（均值、方差、范数），与 FP16 基线离线比对，作为精度漂移的代理信号。三者都是低开销的标量埋点，不引入额外 GEMM。</p>\n<p>回滚闸门要分级，且必须与灰度批次绑定。一级闸门是输出统计量偏离基线超过阈值，自动把该批请求切到 FP16 副本重跑，只影响单批；二级闸门是 drift_j 连续多个窗口超限，触发离线重校准任务并把新平滑因子推入下一版模型，期间编码段维持 FP16；三级闸门是 OOM 或尖刺导致 SLO 违约，直接回滚整段量化配置。分级的意义在于：平滑量化的收益是编码段时延降低约 35–45%，这个收益值得为它保留一条随时可切的 FP16 旁路，而不是让一次分布外流量把整个服务拖垮。回滚本身不贵——视觉 token 本就以 FP16 写入 KV cache，切回 FP16 编码不改变下游接口。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-44\">四十四 · 校准集覆盖度是真正的容量上限</h3>\n<p>所有失败模式最终收敛到同一个工程判断：这套方法的规模上限不是参数量、不是分辨率，而是<strong>校准集对部署分布的覆盖度</strong>。平滑因子 s_j 按校准集估计后固定，它把“激活离群值在哪”这一信息冻结进了权重；一旦线上分布滑出校准集，冻结的信息就变成错误先验。因此监控的核心不是精度分数本身，而是“线上激活分布与校准分布的偏离度”这个前置量——drift_j 是它的通道级投影，输出统计量是它的整体投影。</p>\n<p>工程上的应对是把校准当成持续过程而非一次性动作：按流量域（文档、自然图像、红外、医学）分别维护校准集与对应的平滑因子版本，路由时按域标签选版本；无标签时用输出统计量做域判别，命中未知域就走 FP16 兜底并采样回灌校准集。视频多帧场景要按帧分布重估平滑因子，因为帧间亮度与运动模糊会改变通道极值。这条路径的代价是模型侧要维护多份平滑因子（每份只是 per-channel 向量，存储可忽略），换来的是一定范围内分布漂移不再直接等于精度事故。真正的红线是：不要在没有域标签、没有兜底旁路的情况下，把平滑量化推到全量流量上——末两层 FP16 与整段回滚能力，是这套方法能上生产的前提条件，而不是可选的优化项。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-45\">四十五 · 平滑量化的失效面：从离群值回潮到尾延迟尖刺</h3>\n\n<p>平滑因子 $s_j$ 是离线按校准集估计的固定常量，这既是零运行时开销的来源，也是整套方案最脆的接缝。公式 $s_j = \\max(|x_j|)/\\max(|W_{:,j}|)^{\\alpha},\\ \\alpha\\in[0.4,0.6]$ 中，分子取的是校准图像上第 $j$ 通道激活的最大绝对值——一旦部署流量里出现校准集未覆盖的分布，例如红外热成像的低对比度长尾、医学影像的宽窗宽高动态，该通道的真实离群值会超出 $s_j$ 所“预期”的范围，除以 $s_j$ 后仍然溢出 INT8 的对称量化区间，per-token 动态量化只能缩放整体幅度、无法挽救单通道饱和。表现不是均匀掉点，而是局部崩塌：跨模态注意力对视觉 token 的某几个通道异常敏感，饱和通道会让文本侧对齐分数整体偏移。诊断手段是在线统计每层 LayerNorm 后激活的 per-channel 最大值与 $s_j$ 的比值，把超过阈值的通道计数作为漂移指标上报；该指标一旦抬升，说明校准集覆盖度已不足，必须触发重校准而不是继续调低量化阈值。</p>\n\n<p>系统侧的代价同样是结构性的。INT8 GEMM 的累加器是 INT32，输出反量化回 FP16 再写入 KV cache，这条路径本身不引入额外显存；真正吃掉预算的是“兜底”配置——高分辨率密集预测（OCR、文档）精度下降 1–2 个点，需保留最后两层 FP16，于是视觉编码段里同时存在 INT8 与 FP16 两种 GEMM，cuBLASLt 需要在同一 stream 上切换两种 kernel 族，SM100 上 INT8 相对 FP16 的 2 倍吞吐被末两层的 FP16 段稀释，端到端收益从材料给出的 35–45% 回落到更窄的区间。更隐蔽的是批抖动：批大小按视觉 token 数 $N$ 与显存对齐，而图像分辨率在请求间差异极大，token 数呈长尾分布，调度器若按平均 $N$ 预留显存，遇到超高分图就会触发 OOM 或被迫拆分批次，拆分又破坏了 GEMM 的规整形状，单次编码时延出现尖刺。工程上应把视觉编码段单独设为一条按 token 数分桶的队列，桶边界与 INT8 kernel 的 tile 形状对齐，并对超出最大桶的请求走 FP16 慢路径而非拒绝。</p>\n\n<p>路由不均是多副本部署下的另一类失效：平滑量化后的视觉编码器副本在吞吐上远高于 FP16 副本，若负载均衡仍按请求数而非 token 数加权，INT8 副本会被压到排队、FP16 副本闲置，尾延迟由最慢副本决定。监控应采集每副本的 token/秒、队列深度与 P99 编码时延三个量，用 token 加权而非请求加权做分流。回滚路径必须预置且可秒级切换：把平滑因子与量化权重做成独立版本的制品，与 FP16 权重并存于同一模型仓库，通过运行时开关按模型或按流量比例灰度；一旦漂移指标或 P99 越界，直接摘除 INT8 分支，KV cache 中已写入的 FP16 视觉 token 无需重算，跨模态注意力可无缝继续。切记不要顺手把视觉 token 也压成 INT8 写进 KV cache——材料明确指出这会进一步劣化跨模态注意力精度，而它带来的显存节省远小于其精度风险，属于典型的负收益优化。</p>\n\n<table class=\"mini\">\n<thead><tr><th>失效模式</th><th>可观测信号</th><th>处置</th></tr></thead>\n<tbody>\n<tr><td>离群值回潮（OOD 图像）</td><td>per-channel max/$s_j$ 比值抬升</td><td>重校准平滑因子，灰度前先离线验证</td></tr>\n<tr><td>批抖动 / OOM</td><td>token 分桶溢出计数、拆分批次比例</td><td>按 token 数分桶排队，超限走 FP16 慢路径</td></tr>\n<tr><td>路由不均</td><td>副本 token/秒与队列深度偏离</td><td>token 加权分流，摘除慢副本</td></tr>\n<tr><td>尾延迟尖刺</td><td>视觉编码段 P99 与 P50 的比值</td><td>开关切回 FP16 分支，保留末两层兜底</td></tr>\n</tbody>\n</table>\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-46\">四十六 · 选型的第一性问题：你降的是精度还是数量</h3>\n<p>面对视觉编码器这一段固定开销，工程上可选的加速手段其实分属两条互不干扰的轴：一条轴降低“每个 token 的计算精度”，另一条轴降低“token 的数量”。平滑 INT8 属于前者——它把 LayerNorm 后的通道离群值搬到权重侧，使 QKV 与 MLP 能以 W8A8 跑在第五代 Tensor Core 的 INT8 通路上；视觉缓存复用、双阶段统一 token 缩减、逐层视觉 token 压缩、熵引导剪枝这些条目属于后者，改变的是进入跨模态注意力的序列长度。选型时先问一句：当前瓶颈是 GEMM 的算力占用，还是注意力的序列长度与 KV cache 占用？前者选精度轴，后者选数量轴。两条轴可以叠加，但叠加时精度轴的收益会被数量轴稀释——token 数减半后，编码段 GEMM 的绝对耗时也减半，此时再上 INT8 的边际收益按同一比例缩小，而校准与末两层 FP16 兜底的成本不变。</p>\n<p>第二条判断线是“量化对象是否跨越阶段边界”。平滑 INT8 的部署配方明确把量化限定在编码阶段，视觉 token 以 FP16 写入 KV cache 供后续跨模态注意力使用。多模态全静态量化那条目把量化推到语言侧与 KV cache，收益更大但风险面也更宽；一旦把视觉 token 也压成 INT8 写入 KV cache，跨模态注意力精度会进一步劣化，这是本算法明确的失败模式。因此二者的选择不是“谁更先进”，而是“你是否愿意让量化误差进入解码阶段的注意力读取路径”。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-47\">四十七 · 决策表：五个判据与对应选择</h3>\n<p>下表把相邻算法按判据归位。判据取自重负载特征而非算法名气：任务是否密集预测、分布是否稳定、瓶颈落在算力还是序列、是否允许跨阶段误差传播、以及是否有可用的校准集。</p>\n<table class=\"mini\"><thead><tr><th>判据</th><th>平滑 INT8（本条）</th><th>token 缩减族</th><th>全静态量化</th><th>量化感知剪枝</th></tr></thead><tbody>\n<tr><td>瓶颈定位</td><td>编码段 GEMM 算力</td><td>序列长度 / KV 占用</td><td>端到端含解码</td><td>算力与数量同时</td></tr>\n<tr><td>密集预测（OCR/文档）</td><td>可用，须保留末两层 FP16</td><td>慎用，token 合并损伤细节</td><td>风险最高</td><td>需联合校准</td></tr>\n<tr><td>分布稳定性</td><td>要求校准集覆盖目标分布</td><td>对分布不敏感</td><td>要求最严</td><td>要求严</td></tr>\n<tr><td>运行时开销</td><td>零（因子离线）</td><td>有路由/打分开销</td><td>零</td><td>有打分开销</td></tr>\n<tr><td>与解码阶段耦合</td><td>无（token 保持 FP16）</td><td>无</td><td>强耦合</td><td>弱耦合</td></tr>\n</tbody></table>\n<p>读表的方式是逐行排除：若第一行判定瓶颈在序列而非算力，直接跳到 token 缩减族，不必进入本条的校准流程；若任务属密集预测且不接受任何 token 丢失，则排除缩减族，回到本条并接受末两层 FP16 的兜底代价；若团队无法维护按帧分布重估的校准流水线（视频多帧场景要求按帧分布重估平滑因子），则本条不可用，退化为纯权重 INT8 或维持 FP16。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-48\">四十八 · 平滑因子与缩减比率的代价换算</h3>\n<p>把两条轴的代价放到同一量纲上比较，需要一个粗略的换算。设编码段原时延为 $T_e$，视觉 token 占端到端时延的 20–35%，则端到端为 $T_{e2e}=T_e/\\rho$，$\\rho\\in[0.20,0.35]$。平滑 INT8 使 $T_e$ 降为 $(0.55\\sim0.65)T_e$；token 缩减若把序列长度压到 $kN$（$k&lt;1$），注意力部分近似按 $k$ 或 $k^2$ 缩放，GEMM 部分按 $k$ 缩放。于是：</p>\n<div class=\"formula\">$$\\Delta T_{e2e}^{\\text{int8}}=\\frac{(0.35\\sim0.45)T_e}{\\rho},\\qquad \\Delta T_{e2e}^{\\text{reduce}}\\approx\\frac{(1-k)\\,T_e^{\\text{attn}}+ (1-k)\\,T_e^{\\text{ffn}}}{\\rho}$$</div>\n<p>代入 $\\rho=0.25$ 的中值，INT8 带来的端到端收益约为编码段原时延的 1.4–1.8 倍；而 $k=0.5$ 的 token 缩减在编码段内部即砍掉一半工作量，端到端收益约等于编码段原时延的 2 倍。这说明当缩减比率能做到 2 倍以上时，数量轴的端到端杠杆更大；但缩减比率受精度约束，密集预测任务上往往只能做到温和缩减，此时精度轴的确定性收益反而更划算。工程判断：先测 $k$ 的可达上限，再决定是否值得为 INT8 建校准流水线。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-49\">四十九 · 与量化感知剪枝的联合边界</h3>\n<p>量化感知视觉剪枝与本条在形式上最接近，因为两者都要动 QKV 与 MLP 的权重，且都需要校准数据。差别在于：剪枝改变的是权重矩阵的稀疏结构，平滑改变的是权重的数值尺度分布。二者叠加时的顺序有讲究——应先在 FP16 权重上完成剪枝掩码的确定，再在剪枝后的权重上估计平滑因子 $s_j$，因为 $s_j=\\big(\\max(|x_j|)/\\max(|W_{:,j}|)\\big)^{\\alpha}$ 依赖被剪枝后列的最大值；若先平滑再剪枝，被剪掉的位置会改变 $\\max(|W_{:,j}|)$，使已估因子失配。$\\alpha\\in[0.4,0.6]$ 的取值在剪枝后应偏向区间下沿，因为稀疏化本身已削弱了权重的动态范围，过强的平滑迁移会把剩余权重的离群值放大。</p>\n<p>代价方面，剪枝带来的收益是显存与带宽的下降，而 INT8 带来的是 Tensor Core 吞吐的翻倍（FP16 的 2 倍）；在 B200 上两者叠加时，若稀疏结构不能被 INT8 GEMM 内核有效利用，实际吞吐提升会被内核选择开销吃掉，表现为时延不降反升。这是联合方案最常见的失败形态，诊断方法与本条第七节所述的失败模式不同：不是精度回潮，而是内核利用率不足。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-50\">五十 · 适用条件的三条硬约束</h3>\n<p>第一条硬约束是校准集覆盖度。平滑因子按模型固定，规模受校准集覆盖度限制；遇到红外、医学这类分布外图像，激活离群值回潮，精度不可控。因此本条的适用前提是推理流量中分布外样本占比可估且可隔离——若无法隔离，就必须保留一条 FP16 旁路，按图像来源路由，这本身会引入批内异构，破坏连续批处理的批对齐。</p>\n<p>第二条是分辨率与任务类型。OCR、文档等高分辨率密集预测任务上精度下降 1–2 个点，需保留最后两层 FP16 兜底。这条兜底不是可选项：末两层承载的是与像素级定位强相关的特征，INT8 的量化步长在该尺度上会吞掉细粒度差异。保留末两层意味着编码段时延的收益按层数比例打折，若 ViT 层数较浅，折扣会显著侵蚀 35–45% 的整体收益。</p>\n<p>第三条是视频多帧场景的校准重估成本。按帧分布重估平滑因子意味着校准从一次性离线工作变成周期性工作，工程上要为此维护数据采样与因子版本管理；若团队没有这条流水线，视频场景应直接排除本条，转向对分布不敏感的 token 缩减族。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-51\">五十一 · 决策落地：一个可执行的判定序列</h3>\n<p>把上述判据压成一个顺序判定，便于在容量规划会上直接使用。第一步，测端到端时延分解，确认视觉编码段占比是否落在 20–35%；低于该区间说明瓶颈不在视觉侧，本条与缩减族都不应优先。第二步，判定任务是否密集预测：是，则排除 token 缩减族，进入第三步；否，则先评估缩减比率 $k$ 的可达上限，$k\\le0.5$ 时优先缩减族。第三步，检查校准集是否覆盖线上分布且能周期重估：不能，则本条不可用。第四步，确认量化边界止于编码阶段、视觉 token 以 FP16 写入 KV cache：若业务要求 KV cache 也压缩，转多模态全静态量化并接受更强的耦合风险。第五步，在剪枝与平滑联合时固定“先剪枝、后估因子、$\\alpha$ 取下沿”的顺序，并用 INT8 内核的实际利用率而非理论峰值作为验收指标。</p>\n<p>这套序列的落点是一个工程判断：平滑 INT8 的价值不在其峰值吞吐数字，而在于它以零运行时开销换取了编码段 35–45% 的时延压缩，代价被限制在“校准覆盖度”与“末两层 FP16”这两个可控项上；一旦这两个可控项失控——分布外流量不可隔离，或层数太浅使兜底折扣过大——它的确定性优势就消失，此时应把预算投向 token 数量轴，而不是继续在精度轴上加固。</p>\n\n<h3 id=\"alg-vision-encoder-int8-smooth-sec-52\">五十二 · 同族算法的选择边界：平滑量化在什么条件下才值得上</h3>\n<p>把视觉编码器压到INT8，工程上至少有四条路：纯权重INT8（激活仍FP16）、per-tensor激活量化、本节的通道级平滑W8A8、以及视觉token压缩/合并。它们不是同一维度的替代品，选错的代价也不同。纯权重INT8只动权重，激活保持FP16，GEMM仍是混合精度，拿不到第五代Tensor Core的INT8双倍吞吐，视觉段时延改善有限，但几乎不损精度，适合校准集覆盖不足、分布外风险高的场景。per-tensor激活量化实现最简，一个全局scale搞定，代价是ViT激活通道动态范围大，单scale被最大离群通道绑架，其余通道的有效位数被压掉，精度崩塌正是本节要解决的起点。平滑量化把离群值从激活搬到权重，用$$\\hat{x}_j = x_j / s_j,\\quad \\hat{W}_{:,j} = W_{:,j}\\cdot s_j,\\quad s_j = \\frac{\\max(|x_j|)}{\\max(|W_{:,j}|)}^{\\alpha},\\ \\alpha\\in[0.4,0.6]$$做通道级重平衡，换来真正的W8A8与零运行时开销，代价是引入校准依赖和末两层FP16兜底。token压缩/合并则与前三者正交——它降token数量而非计算精度，可与平滑量化叠加，但单独使用时省的是注意力与FFN的规模，不改变单token的GEMM精度。</p>\n<p>决策的第一道分水岭是精度预算与任务形态。OCR、文档这类高分辨率密集预测，输出对细小字符的激活极值敏感，平滑量化在此有1–2个点的精度下降，必须保留最后两层FP16；若SLO允许的精度余量小于这个量级，就不该上W8A8，退回纯权重INT8更稳。第二道分水岭是分布稳定性：平滑因子按模型固定、由少量校准图像离线估计，遇到红外、医学等分布外图像时激活离群值回潮，精度不可控，此时要么重新校准，要么直接放弃该方案。第三道是端到端收益结构：视觉token占端到端时延的20–35%，是固定开销，编码段降35–45%意味着端到端只有个位数到十几个百分点的改善；若解码段或跨模态注意力才是主瓶颈，视觉量化的边际收益会被稀释，优先级应让给KV cache与批调度。第四道是KV cache的写入精度：视觉token以FP16写入供跨模态注意力使用，若顺手把KV cache也压成INT8，跨模态注意力精度会进一步劣化，这条边界不能越。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>激活精度</th><th>典型精度风险</th><th>运行时开销</th><th>适用条件</th></tr></thead><tbody><tr><td>纯权重INT8</td><td>FP16</td><td>低</td><td>无</td><td>校准集覆盖不足、分布外多</td></tr><tr><td>per-tensor激活INT8</td><td>INT8</td><td>高（离群通道绑架scale）</td><td>无</td><td>激活动态范围本身温和</td></tr><tr><td>通道平滑W8A8</td><td>INT8</td><td>中（密集预测降1–2点）</td><td>零（离线校准）</td><td>分布稳定、可留末两层FP16</td></tr><tr><td>token压缩/合并</td><td>不变</td><td>低–中（信息丢失）</td><td>有（排序/合并）</td><td>与上述正交，可叠加</td></tr></tbody></table>\n<p>系统代价要按段算而不是按算子算。INT8 GEMM在B200上峰值吞吐为FP16的2倍，累加器INT32，输出反量化回FP16，这条路径的收益上限由视觉段在端到端中的占比封顶：占比20%时，编码段降45%只换来端到端约9%的时延改善；占比35%时约16%。这就是为什么该方案的正确用法是“先把视觉段从固定开销里削掉，再谈解码优化”，而不是把它当成全局加速器。规模上限受校准集覆盖度约束：视频多帧场景需按帧分布重估平滑因子，否则跨帧的亮度与运动模糊会把离群值带回激活侧；材料未给出参数量或分辨率上限，工程判断应落在“校准图像能否代表线上流量分布”这一条上。若线上存在多路来源（监控红外、内窥镜、扫描文档）混跑，按来源分组维护多套平滑因子比强行共用一套更可靠，代价是模型副本与显存占用上升，需与批调度一起权衡。最终选择应写成一条可执行的判据：视觉段占比高、分布可校准、精度余量能容纳1–2点下降且允许末两层FP16，则上平滑W8A8；任一条不满足，退回纯权重INT8并把优化预算移向token压缩与KV cache。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · 多模态批调度与缓存复用</td></tr><tr><td>解决什么</td><td>视觉编码器在Blackwell上仍以FP16运行，ViT的激活动态范围大导致直接INT8量化精度崩塌，而视觉token…</td></tr><tr><td>一句话机制</td><td>在ViT的LayerNorm后对激活做通道级平滑缩放，把离群值从激活搬到权重，再对QKV与MLP做W8A8 INT8 …</td></tr><tr><td>代价与失效</td><td>对高分辨率密集预测任务（OCR、文档）精度下降1–2个点，需保留最后两层FP16；平滑因子按模型固定，遇到分布外图像（红外、医学）时激活离…</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-vision-encoder-int8-smooth · 共 8 个片段</p>\n";break;}}})();
